(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-rm-verifier-disagg-serving"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-1\">一 · 事故现场：一次打分抖动如何拖垮整条 RL 迭代</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-2\">二 · 它到底解决什么：生成与打分的时间解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-3\">三 · 它不解决什么：边界要划清楚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-4\">四 · 失败模式：队列与幂等是两条命门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-5\">五 · 一个可操作的判断例子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-6\">六 · 奖励服务独立拆分的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-7\">七 · 入队：样本从生成侧流向打分侧的那一跳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-8\">八 · 分桶攒批：把变长 prefill 拼成高效批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-9\">九 · 打分与回填：标量结果如何回到训练侧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-10\">十 · 重叠结构：迭代时间由最大值决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-11\">十一 · 弹性与故障：队列深度驱动的扩缩容与幂等边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-12\">十二 · 解耦的代价：队列水位、幂等回填与显存再分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-13\">十三 · 迭代时间公式的逐项拆解与重叠条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-14\">十四 · 奖励吞吐公式与分桶的定量作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-15\">十五 · 队列与回填的伪代码骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-16\">十六 · 独立 KV 池与权重共享的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-17\">十七 · 弹性扩缩容的触发判据与失效路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-18\">十八 · 与训练侧 batch 组装的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-19\">十九 · 流水线重叠的失效边界与幂等代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-20\">二十 · 请求形态：变长完整序列的 prefill 打分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-21\">二十一 · 长度分布决定分桶粒度与 padding 浪费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-22\">二十二 · 并发与批大小：队列深度是唯一有效的控制量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-23\">二十三 · 负载不对时：重叠退化为串行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-24\">二十四 · 显存与弹性的耦合：小集群上的负载错配代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-25\">二十五 · 幂等与负载配方的交叉约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-26\">二十六 · 负载配方：变长 prefill 打分与队列深度决定重叠成败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-27\">二十七 · 硬件档位：按奖励模型的 prefill 形态选卡，而不是按策略模型选卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-28\">二十八 · 并行拓扑：TP 沿序列维摊薄时延，PP 不适用于打分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-29\">二十九 · 量化方案：奖励打分对数值误差的容忍度低于生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-30\">三十 · KV 策略与权重存储共享：独立池、共享盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-31\">三十一 · 调度参数：队列深度是弹性扩缩容的唯一触发量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-32\">三十二 · 奖励服务的部署配方边界：分桶攒批的收益何时被队列与显存吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-33\">三十三 · 显存：独立权重是固定开销，KV 池才是弹性变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-34\">三十四 · 带宽：prefill 打分是访存受限，不是算力受限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-35\">三十五 · 通信：队列传输量小，但回填路径的时延不可忽略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-36\">三十六 · 功耗与弹性：扩缩容粒度决定规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-37\">三十七 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-38\">三十八 · 奖励服务先崩在哪：队列深度、显存配额与回填幂等</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-39\">三十九 · 精度漂移：从打分标量到训练信号的失真链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-40\">四十 · OOM 与降批：显存争抢的三种触发路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-41\">四十一 · 批抖动与路由不均：异步重叠失效的两个前兆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-42\">四十二 · 尾延迟尖刺：从 P99 回溯到具体机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-43\">四十三 · 幂等与回滚：故障恢复的最小工程闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-44\">四十四 · 监控面板与容量判断：把失败模式映射成可观测指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-45\">四十五 · 当重叠失效：队列、幂等与显存的三类塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-46\">四十六 · 同族算法的选择维度：先问&quot;瓶颈在哪一侧&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-47\">四十七 · 决策表：五类相邻算法的适用条件对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-48\">四十八 · 吞吐匹配的定量判据：队列深度与两侧速率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-49\">四十九 · 与&quot;预填解码分离&quot;和&quot;KV 池化&quot;的边界划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-50\">五十 · 组合选型的工程判断：按集群规模分档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-rm-verifier-disagg-serving-sec-51\">五十一 · 同族对照：何时拆、何时合、何时换验证器</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:563px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 563.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout引擎生成完一条样本后，将token序列与元数据写入奖励服务队…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">奖励服务按序列长度分桶，攒批后做prefill打分，输出标量reward或…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">打分结果按样本id回填到训练侧的样本缓冲区，与rollout流水线异步重叠</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练侧在攒够一个batch的样本与reward后启动策略更新，奖励服务继续…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">奖励服务按队列深度独立扩缩容，与rollout引擎共享权重存储但使用独立K…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-1\">一 · 事故现场：一次打分抖动如何拖垮整条 RL 迭代</h3>\n<p>某 RLVR 训练任务在 GB200 NVL72 上跑得正顺：策略模型 rollout 侧用连续批处理把 decode 压到接近显存带宽上限，单卡吞吐看起来无可挑剔。问题出在奖励侧——验证器与策略模型同卡混部，共享同一块 HBM 与同一组 SM。rollout 每生成完一条完整长序列，验证器就要对这条序列做一次全量 prefill；这条 prefill 的 token 数往往是 decode 步长的几十倍，KV 占用瞬间抬升，把正在解码的 batch 挤到降批甚至抢占。更糟的是，验证器输入长度分布极不均匀：数学推理样本动辄数千 token，而短答案样本只有几百 token，混在同一批里 padding 浪费严重，SM 利用率被最短序列拖住。表现到训练侧就是迭代时间抖动：有的 step 因为奖励打分排队而空转，有的 step 因为 decode 被 prefill 打断而吞吐骤降。工程上把这种状态叫“混部互踩”——两类负载的 batch 组成、并行度偏好、显存占用曲线完全不同，却被强行塞进同一张卡。</p>\n<p>这个事故的关键不在于某一侧慢，而在于两侧的慢互相放大：rollout 的 decode 是延迟敏感、低算术强度的，奖励的 prefill 是吞吐敏感、高算术强度的；前者怕被打断，后者怕攒不起批。同卡部署时，调度器无论偏向哪一侧，另一侧都会付出代价。端到端迭代时间从理想的重叠形态退化为串行相加，$$T_{\\text{iter}} \\approx T_{\\text{rollout}} + T_{\\text{reward}} + T_{\\text{train}}$$，而训练侧等待的每一秒都是 GPU 空转的功耗与机会成本。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-2\">二 · 它到底解决什么：生成与打分的时间解耦</h3>\n<p>奖励模型分离式服务要解决的是一个非常具体的推理问题：把奖励模型/验证器的打分推理从策略 rollout 引擎中拆出去，变成独立服务，让生成与打分在时间上重叠而非串行。拆分之后，rollout 引擎生成完一条样本，只做一件事——把 token 序列与元数据写入奖励服务队列，然后立刻回去继续采样，不阻塞。奖励服务按自己的节奏消费队列：按序列长度分桶、攒批、做 prefill 打分，输出标量 reward 或验证器通过信号，再按样本 id 异步回填到训练侧样本缓冲区。训练侧攒够一个 batch 的样本与 reward 就启动策略更新，此时奖励服务已经在处理下一批。</p>\n<p>这一步解耦带来的直接收益写在公式里：$$T_{\\text{iter}} \\approx \\max\\left(T_{\\text{rollout}},\\ T_{\\text{reward}}\\right) + T_{\\text{train}}$$。迭代时间由两侧的较大者决定，而不是两者之和。重叠程度取决于队列深度与两侧吞吐是否匹配——队列太浅，奖励服务来不及攒批就被迫开工，prefill 效率塌陷；队列太深，回填时延拉长，训练侧等 reward 等到流水线断流。队列深度因此不是随便设的缓冲参数，而是决定这条流水线能否成立的核心调度变量。</p>\n<p>奖励服务独立后，batch 组成终于可以按自身最优来组织。分桶攒批使同批序列长度接近，padding 浪费被压下去；prefill 的算术强度得以拉满，打分吞吐相对混部形态有实质提升。吞吐的量化表达是 $$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$——分母是各样本长度除以奖励 prefill 吞吐的累加，分子是样本数。这个式子说明两件事：奖励吞吐对长序列极其敏感，且分桶减少 padding 等价于减小分母中的无效项。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-3\">三 · 它不解决什么：边界要划清楚</h3>\n<p>第一，它不解决奖励模型本身算得慢的问题。分离只是把打分挪到独立资源上并行，若奖励模型参数量大、prefill 吞吐低，$T_{\\text{reward}}$ 依然会成为 $\\max$ 里的支配项，此时正确动作是换更优的并行拓扑或量化精度，而不是继续加深队列。第二，它不解决 rollout 侧的 decode 效率问题——连续批处理、分页 KV、投机解码属于别的条目，本算法只保证打分不打断 decode。第三，它不解决奖励模型与策略模型之间的语义一致性，也不处理 reward hacking；打分逻辑的正确性不在服务拆分的范畴内。第四，它不适用于奖励计算极轻的场景：若验证器只是规则匹配或极短序列的标量判断，拆出独立服务的队列维护、结果回填、幂等处理开销会超过重叠收益，同卡内联反而更省。第五，它不解决跨节点通信本身的带宽瓶颈——样本队列走的是主机侧或 RDMA 路径，序列 token 的搬运量随样本长度线性增长，长序列高采样率时队列带宽会成为新的隐性瓶颈。</p>\n<p>还有一个容易被忽略的边界：分离式服务把奖励权重独立占用一份显存。在小规模集群上，这份额外权重与策略模型、KV 池争抢 HBM，弹性伸缩不及时就会触发 OOM 或被动降批。规模上限因此受队列深度与伸缩粒度约束——集群越小，拆分的显存代价占比越高，收益越容易被抵消。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-4\">四 · 失败模式：队列与幂等是两条命门</h3>\n<p>最典型的失败是奖励服务故障或重启。队列中的样本要么丢失，要么被重复消费；若回填缺少幂等键，训练侧会混入重复 reward 或缺失样本，策略更新被污染，而这种污染往往在若干 step 后才以 loss 异常的形式暴露。工程上的对策是把样本 id 作为幂等键贯穿队列、打分、回填三段，回填端做去重与缺失检测，队列持久化到可恢复的存储而非纯内存。</p>\n<p>第二种失败是队列深度与两侧吞吐不匹配。奖励服务成为瓶颈时，队列持续增长，回填时延拉长，训练侧等不到 reward，异步重叠失效，端到端时间退化为两者之和——公式里的 $\\max$ 悄悄变回了 $+$。反过来，奖励服务产能过剩时队列长期为空，攒批失败，prefill 效率下降，独立部署的显存代价却照付。判断依据很直接：观察队列深度的稳态分布与回填时延的分位数，若队列单调增长或长期贴底，就说明两侧吞吐失配，需要调整扩缩容触发点或重新分配硬件档位。</p>\n<p>第三种失败是弹性伸缩粒度太粗。奖励服务按队列深度独立扩缩容，但扩缩容本身有冷启动成本：加载权重、建立 KV 池、加入服务发现。伸缩慢于队列增长时，短时尖峰直接打成 OOM 或降批，打分吞吐掉下去又反过来加剧队列积压。因此扩容触发点要留出提前量，且奖励服务与 rollout 引擎共享权重存储、使用独立 KV 池的设计，正是为了把冷启动中的权重加载成本压到最低。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-5\">五 · 一个可操作的判断例子</h3>\n<p>设想一条数学推理 RLVR 流水线：rollout 侧每步生成一批变长完整序列，长度从数百到数千 token 不等；验证器需要读完整序列做逐 token 的打分或校验。混部时，验证器的 prefill 与 rollout 的 decode 在同一张卡上交替抢占，迭代时间抖动明显，且长序列样本越多抖动越剧烈。拆分为独立服务后，rollout 侧写入队列即返回，验证器按长度分桶攒批，同批内序列长度接近，padding 显著减少，prefill 吞吐抬升；训练侧按样本 id 回填 reward，攒够 batch 即更新。此时端到端时间由 $\\max(T_{\\text{rollout}}, T_{\\text{reward}})$ 支配——若 rollout 是长 pole，奖励服务就有余量处理积压；若验证器是长 pole，则需按队列深度扩容或改用更优 prefill 配置。</p>\n<p>这个例子的工程判断点在于：先测两侧单独运行时的吞吐与尾延迟，再算队列稳态深度，最后决定是否拆分以及拆分的硬件档位。拆分不是默认正确，而是当 $T_{\\text{reward}}$ 与 $T_{\\text{rollout}}$ 量级相当、且混部互踩造成的抖动超过队列维护开销时才成立。若两者量级悬殊，分离的收益会被额外显存占用与队列时延吃掉。判断的落点始终是那条 $\\max$ 公式：只有当重叠真正发生，拆分才把加法变成取大。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-6\">六 · 奖励服务独立拆分的失效边界与系统代价</h3>\n<p>这套方案真正要解决的，是 RLHF/RLVR 训练回路里一个被混部掩盖的推理形态错配问题：策略模型的 rollout 是自回归 decode，逐 token 生成、KV 池随序列增长、batch 组成随采样动态变化；而奖励模型或验证器是完整长序列的一次性 prefill 打分，输入长度由样本决定、输出只有一个标量或通过信号。两者同卡部署时，奖励 prefill 会瞬时吃掉大量显存与算力，把正在 decode 的 rollout 挤到降批甚至抢占 KV 池，rollout 的 token 间延迟被拉长，整批样本的生成时间被拖慢。一个典型的线上事故形态是：rollout 引擎在长序列样本上攒批到一半，奖励模型的一次大批 prefill 触发显存峰值，rollout 侧被迫驱逐 KV 块重算，采样吞吐骤降，训练侧等不到足够样本，迭代周期被拉长到远超预期；更糟的是，奖励打分与 rollout 在同一进程内串行排队，端到端时间退化为两者之和。拆分服务的动机正是把这条串行链改成两条可重叠的流水线，让迭代时间由较慢的一侧决定，而不是两侧相加。</p>\n<p>但重叠不是免费的，它的成立条件写在队列深度与两侧吞吐的匹配关系里。设一批样本的生成时间为 $T_{\\text{rollout}}$、对应打分时间为 $T_{\\text{reward}}$，端到端迭代时间近似为</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(T_{\\text{rollout}},\\ T_{\\text{reward}}\\right) + T_{\\text{train}}$$</div>\n<p>这个式子只有在奖励服务始终有活可干、rollout 侧不因回填阻塞时才成立。一旦队列深度不足，奖励服务空转等样本，重叠退化为串行，$T_{\\text{iter}}$ 回到 $T_{\\text{rollout}} + T_{\\text{reward}} + T_{\\text{train}}$；反过来，若奖励服务吞吐低于 rollout 产出速率，队列持续积压，奖励侧成为瓶颈，端到端时间同样退化为两者之和，且回填时延拉长会推迟训练侧攒批。奖励服务的吞吐本身由分桶后的批效率决定：</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$</div>\n<p>长序列样本占比高、长度方差大时，分桶攒批的填充浪费与批内最长序列的拖尾会压低有效吞吐，此时即便队列很深，奖励服务也追不上 rollout。这是该方案第一个明确的失效条件：奖励模型 prefill 吞吐与 rollout 产出速率不匹配，且弹性扩缩容粒度跟不上队列深度的变化速度。</p>\n<p>第二个失效条件在故障语义上。奖励服务与 rollout 引擎之间靠样本队列和结果回填解耦，队列中的样本在奖励服务重启或扩缩容时会丢失，重复投递则会导致同一样本被打分两次。若回填缺少幂等键，训练侧样本缓冲区会混入重复 reward 或缺失样本，策略更新用到错误的优势估计，这种污染不会立刻报错，而是以训练曲线漂移的形式延迟暴露。工程上必须让每条样本携带唯一 id、回填按 id 去重、队列消息具备至少一次投递语义并配合训练侧校验样本数与 reward 数的一致性。第三个代价是显存：奖励服务独立占用一份权重，并使用独立 KV 池，虽然与 rollout 引擎共享权重存储，但在小模型集群上这份额外权重与 KV 池会和策略模型争抢显存，弹性伸缩不及时就会触发 OOM 或被动降批。规模上限因此受队列深度与伸缩粒度约束——队列太浅重叠不足，队列太深则故障时丢失的样本更多、回填延迟更长。适用边界可以归纳为一张简表：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>方案成立</th><th>方案退化</th></tr></thead><tbody><tr><td>奖励吞吐 vs rollout 产出</td><td>奖励侧吞吐不低于产出速率，队列稳定在浅水位</td><td>奖励侧持续积压，端到端退化为两者之和</td></tr><tr><td>故障与回填</td><td>样本 id 幂等、队列可重放、训练侧校验数量</td><td>样本丢失或重复打分，优势估计被污染</td></tr><tr><td>显存预算</td><td>集群显存足以容纳独立权重与独立 KV 池</td><td>小集群争抢显存，OOM 或降批</td></tr><tr><td>弹性粒度</td><td>扩缩容触发点跟随队列深度，粒度细</td><td>伸缩滞后，队列深度震荡</td></tr></tbody></table>\n<p>它不解决的问题同样清晰：拆分不改变奖励模型本身的打分质量与偏差，不解决验证器判定规则的正确性，也不替代训练侧的样本筛选策略；它只把奖励推理从 rollout 的显存与算力竞争中挪出来，换取流水线重叠。对奖励模型极轻、打分几乎不耗时的场景，拆分的队列与回填开销反而超过收益，同卡串行更简单；对奖励模型与策略模型规模相当、单卡放不下两份权重的场景，拆分需要额外的硬件档位，容量规划必须先算清奖励服务的独立显存占用与峰值 prefill 激活，再决定队列深度与扩缩容阈值。</p>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-7\">七 · 入队：样本从生成侧流向打分侧的那一跳</h3>\n<p>奖励分离式服务的第一步发生在 rollout 引擎完成一条样本的瞬间。此时引擎手里握着的是完整的 token 序列（prompt 加生成部分）、样本 id、长度、所属 prompt 分组以及采样参数等元数据。这一步的输出不是 reward，而是一条入队记录：序列本体加上足以让下游定位与回填的键。关键设计判断在于，入队动作必须是非阻塞的——rollout 引擎把记录写入奖励服务的队列后立刻返回继续采样，生成与打分在时间轴上就此解耦。如果这里做成同步 RPC，rollout 的 decode 循环会被奖励侧的长 prefill 拖住，分离带来的收益当场归零。</p>\n<p>入队的代价主要落在主机侧内存与队列带宽上，而不是 GPU。一条长序列的 token id 加上元数据，量级在几十 KB 到上百 KB；队列深度为 $D$ 时，驻留内存约为 $D$ 乘以单条记录大小，这部分必须与两侧的吞吐匹配一起规划。队列本身要有背压：当深度逼近上限，rollout 侧应降速或暂挂新样本入队，而不是无限堆积把主机内存吃穿。工程上更常见的做法是给队列设两个水位——低水位触发奖励服务扩容，高水位触发 rollout 侧限流。</p>\n<p>入队这一跳还决定了后续幂等处理的可行性。样本 id 必须在入队时就固定并随记录一路携带，因为奖励服务可能重启、队列可能重投、结果可能重复回传。缺少稳定键，训练侧就无法判断一条 reward 是新结果还是重放。具体例子：一个 prompt 组采样 8 条，若其中一条在奖励服务重启后被打分两次，训练侧按样本 id 去重即可丢弃后到的那份，而按到达顺序追加则会把这条样本的权重算错。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-8\">八 · 分桶攒批：把变长 prefill 拼成高效批</h3>\n<p>奖励服务的调度器从队列取记录时，第一件事是按序列长度分桶。奖励模型与验证器的输入是完整长序列，prefill 阶段的算力消耗随长度增长，而一个 batch 内若长短混杂，padding 会把短序列的有效计算占比压得很低。分桶的作用是让同批序列长度接近，把 padding 浪费压到可接受范围。桶的粒度是调参对象：桶太粗，批内长度方差大；桶太细，每桶攒不满，批大小上不去，tcgen05 的 MMA 利用率下降。</p>\n<p>攒批的触发条件是双重的——桶内样本数达到目标批大小，或桶内最老样本的等待时间逼近回填时延的容忍上限。前者保吞吐，后者保时延。这一步的输出是一个待打分的批，输入是若干条同长度区间的序列。代价体现在两个方向：攒批等待直接计入回填时延，队列深度不足时等待时间被拉长；批大小受限于奖励模型在该长度下的显存占用，KV 池按批内最长序列乘以批大小预留。</p>\n<p>打分吞吐的估算可以直接写成公式：</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$</div>\n<p>分母是各样本长度除以奖励服务 prefill 吞吐的累加，含义是这批样本的总打分时间由总 token 量与单位时间 prefill 能力决定。这个式子给出一个直接判断：奖励服务的吞吐瓶颈在 prefill 而非 decode，因为打分只需一次前向、输出一个标量或通过信号，decode 几乎不存在。因此奖励服务的并行拓扑应按自身最优 prefill 配置选择，而不是照搬策略模型的 decode 优化配置。具体例子：验证器类奖励模型往往比策略模型小得多，其最优配置可能是更高的张量并行度换更短的单批时延，而不是追求大 batch。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-9\">九 · 打分与回填：标量结果如何回到训练侧</h3>\n<p>批进入奖励模型后走一次完整 prefill，取最后一个有效 token 位置的隐状态接打分头，输出标量 reward；验证器形态则输出通过或不通过的信号，或按规则校验后的二值结果。这一步的输出按样本 id 回填到训练侧的样本缓冲区，回填同样是异步的——训练侧不阻塞等待，而是在自己的循环里检查缓冲区中哪些样本已经凑齐 reward。</p>\n<p>回填路径的代价是时延与一致性。时延上，一条样本从入队到 reward 落进缓冲区，经历了排队等待、攒批等待、prefill 执行、结果传输四段，其中前两段是可变且占主导的。一致性上，回填必须幂等：同一 id 的结果重复到达时覆盖而非追加，缺失时训练侧要有超时判定。训练侧的样本缓冲区因此需要按 id 索引，而不是按到达顺序排列的列表。</p>\n<p>训练侧的启动条件是攒够一个 batch 的样本与对应 reward。这里有一个容易被忽略的耦合：如果训练 batch 的组成要求同一 prompt 组的全部采样都到齐才能计算组内相对优势，那么回填的尾延迟——最慢那条样本的 reward 到达时间——直接决定训练启动时刻。奖励服务分桶攒批时若把同一组的样本打散到不同桶、不同批，尾延迟会被拉长。缓解手段是在分桶键里带上分组信息，或对同组样本做亲和调度。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-10\">十 · 重叠结构：迭代时间由最大值决定</h3>\n<p>三个步骤串起来形成的流水线，其端到端迭代时间由下式刻画：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(T_{\\text{rollout}},\\ T_{\\text{reward}}\\right) + T_{\\text{train}}$$</div>\n<p>$T_{\\text{rollout}}$ 是一批样本的生成时间，$T_{\\text{reward}}$ 是对应打分时间，$T_{\\text{train}}$ 是策略更新耗时。这个式子的成立有前提：两侧吞吐匹配且队列深度足以吸收抖动。重叠程度取决于队列深度——队列太浅，奖励服务一旦短暂变慢，rollout 侧就被背压卡住，最大值退化为两者之和；队列太深，驻留内存与故障时的重放代价上升。工程上的目标是让队列深度覆盖一个打分批的周期，使奖励服务在任何一个批的执行期间都有下一批可攒。</p>\n<p>这一步的系统代价体现在显存与功耗的分配上。奖励服务独立占用一份权重显存，使用独立 KV 池，与 rollout 引擎只共享权重存储（同一份权重文件，不共享运行时副本）。这意味着总显存需求是策略模型权重加 KV 池加奖励模型权重加其 KV 池。在小规模集群上，这份额外权重会与策略模型的 KV 池争抢空间，弹性伸缩不及时就会触发 OOM 或被迫降批。功耗侧，奖励服务在攒批等待期间可以处于低占用状态，按队列深度做弹性伸缩正是为了把这部分空闲功耗收回来。</p>\n<p>具体例子：一个 RLVR 任务里策略模型生成 512 token 的推理链，验证器只需读完整序列做规则校验加一次前向。若两者同卡混部，验证器的长 prefill 会打断策略模型的 decode 连续性，decode 的批不变性被破坏，采样分布随之漂移；分离后验证器在独立卡上按长度分桶攒批，策略模型的 decode 批保持稳定，两侧各自跑在自己的最优配置上。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-11\">十一 · 弹性与故障：队列深度驱动的扩缩容与幂等边界</h3>\n<p>奖励服务的副本数按队列深度独立扩缩容，与 rollout 引擎的规模解耦。触发点是队列深度持续高于阈值一段时间，缩容则在深度持续低于阈值后执行。伸缩粒度受限于奖励模型的加载时间——权重加载与 KV 池初始化不是瞬时动作，因此扩容决策必须提前于队列真正积压。这一步的代价是扩容期间的冷启动窗口：新副本尚未就绪时，已有副本承担全部队列，回填时延上升；若窗口长于训练侧的等待容忍，训练侧会看到 reward 到达速率下降而非中断。</p>\n<p>故障处理是本机制最脆弱的一环。奖励服务重启时，队列中未确认的样本面临丢失或重复打分两种风险。幂等键在此承担全部责任：入队时写入的样本 id 随记录持久化，结果回填时携带同一 id，训练侧按 id 覆盖写入。若队列本身不做持久化，重启即丢失，训练侧只能靠超时判定把缺失样本重新提交给 rollout 引擎重采样——这条路径代价高，因为它把已经花掉的生成算力作废。更稳的做法是队列持久化加确认机制，样本在被奖励服务确认处理后才从队列移除。</p>\n<p>规模上限由队列深度与弹性伸缩粒度共同约束。队列深度决定了能吸收多少抖动，伸缩粒度决定了能多快响应持续积压。当奖励模型相对策略模型很小、副本可以密集部署时，伸缩粒度细，上限高；当奖励模型本身很大、单副本加载慢时，伸缩粒度粗，队列深度必须开得更大来覆盖冷启动窗口，驻留内存随之上升。这条权衡线是容量规划里必须显式写出的参数，而不是留给运行时自适应。</p>\n<p>最后落在工程判断上：奖励分离式服务的正确性不取决于打分本身，而取决于入队键的稳定性、回填的幂等性、以及队列深度与两侧吞吐的匹配。三者任一失守，$T_{\\text{iter}}$ 就从最大值退化为和，分离式部署的全部收益被抵消。因此在把奖励模型拆出去之前，先把样本 id 的生命周期和队列的持久化语义定死，比调批大小和桶粒度更优先。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-12\">十二 · 解耦的代价：队列水位、幂等回填与显存再分配</h3>\n<p>分离式奖励服务的收益全部押在一个前提上：两侧吞吐匹配，且队列始终有货。设奖励侧单序列打分时间为 $L/\\text{thr}_{\\text{reward\\_prefill}}$，则队列的稳态水位由生成速率与打分速率的差积累而成：$Q(t)=\\int_0^t \\left(\\lambda_{\\text{rollout}}-\\mu_{\\text{reward}}\\right)\\mathrm{d}t$。当 $\\lambda&gt;\\mu$ 持续存在，队列单调上涨，$T_{\\text{iter}}$ 从 $\\max(T_{\\text{rollout}},T_{\\text{reward}})$ 退化为两者之和——异步重叠失效，奖励服务变成硬瓶颈。反过来，若 $\\mu$ 远大于 $\\lambda$，奖励侧长期低水位运行，攒批攒不满，prefill 的有效 batch 被队列深度而非分桶策略限制，吞吐掉到单序列水平。工程上必须把扩缩容触发点绑在队列深度与排队时延上，而不是 GPU 利用率：奖励服务是纯 prefill 负载，利用率高但队列短，说明并行度已过剩。</p>\n<p>回填路径的失效条件比吞吐更隐蔽。样本从 rollout 引擎写入队列、经打分、按样本 id 回填训练侧缓冲区，这条链路上任何一次重启都会造成丢失或重复。若回填只带样本 id 而无幂等键（如 rollout 轮次 + 样本序号 + 打分版本），训练侧会把重复 reward 当作新样本混入，梯度被同一序列加权两次；缺失样本则让 batch 组成偏移。代价是训练侧必须维护一份待回填样本的位图或去重表，并在攒批启动策略更新前做完整性校验，这引入了额外的同步点——校验本身会把异步流水线拉回半同步状态，队列越深，校验窗口越长。</p>\n<p>显存账要单独算。奖励服务独立持有一份权重，与 rollout 引擎共享权重存储但使用独立 KV 池，意味着同一集群上权重被驻留两次（存储层共享不等于显存共享）。小模型集群上，策略权重、rollout KV 池、奖励权重、奖励 KV 池四者争抢同一批 HBM，弹性伸缩不及时就会触发 OOM 或被动降批。判断边界很直接：当奖励模型权重占单卡显存的比例超过 rollout KV 池可压缩的余量时，分离部署在小集群上不划算，应退回同卡分时复用。规模上限因此不由 GPU 数量决定，而由队列深度可容忍的时延与伸缩粒度共同决定。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>$\\lambda&gt;\\mu$ 持续</td><td>迭代时间退化为和，重叠失效</td><td>按队列深度扩缩容</td></tr><tr><td>回填缺幂等键</td><td>重复/缺失 reward 污染梯度</td><td>位图校验 + 打分版本号</td></tr><tr><td>权重显存二次驻留</td><td>小集群 OOM 或降批</td><td>按权重占比决定是否分离</td></tr></tbody></table>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-13\">十三 · 迭代时间公式的逐项拆解与重叠条件</h3>\n<p>端到端迭代时间写作 <span class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(T_{\\text{rollout}},\\ T_{\\text{reward}}\\right) + T_{\\text{train}}$$</span> 这个式子的关键在于它不是恒等式，而是一个<strong>带条件的上界</strong>。逐项看：$T_{\\text{rollout}}$ 是策略引擎把一批样本全部生成完毕的墙钟时间，其内部由解码步数与每步 decode 时延决定；$T_{\\text{reward}}$ 是奖励服务把同一批样本全部打分完毕的时间，其内部是纯 prefill 主导——因为奖励模型只需对完整序列做一次前向得到标量，没有自回归解码环节；$T_{\\text{train}}$ 是训练侧拿到整批 (sample, reward) 后做策略更新的时间，它与前两者不重叠，是串行段。</p>\n<p>max 成立的前提是两侧真正流水：第 $k$ 批的 reward 计算必须与第 $k+1$ 批的 rollout 在时间轴上交错。设队列深度为 $D$（缓冲中待打分样本数），重叠的充要条件是稳态下奖励服务的吞吐 $\\ge$ rollout 的样本产出速率。若记 rollout 每秒产出 $r$ 条样本、奖励服务每秒处理 $s$ 条，则当 $r &gt; s$ 时队列单调增长，$T_{\\text{reward}}$ 被拉长到超过 $T_{\\text{rollout}}$，max 退化为 $T_{\\text{reward}}$；更糟的是队列打满后 rollout 被迫阻塞写入，端到端时间退化为 $T_{\\text{rollout}} + T_{\\text{reward}}$ 的和式——这正是异步重叠失效的判据。因此工程上应把 $s/r$ 作为容量规划的第一指标，留出余量而非卡在 1.0。</p>\n<p>具体例子：一批 512 条样本，rollout 侧以每步一条的节奏生成、平均长度 4K token，奖励服务用分桶攒批后单批 32 条做 prefill。若奖励侧单批 prefill 时延低于 rollout 产出 32 条样本的时间，则 max 成立；反之队列深度持续爬升，回填时延（从样本生成完到 reward 回填的间隔）线性增长，训练侧等待整批 reward 的时间被拖长。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-14\">十四 · 奖励吞吐公式与分桶的定量作用</h3>\n<p>吞吐公式 <span class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$</span> 的分母不是样本数而是总 token 量除以 prefill 吞吐，这说明奖励服务的产能由<strong>token 吞吐</strong>而非请求数决定。逐项解释：$N_{\\text{samples}}$ 是批内样本条数，$L_{\\text{sample}}$ 是第 $i$ 条样本的 token 长度，$\\text{thr}_{\\text{reward\\_prefill}}$ 是奖励模型在目标硬件上的 prefill token/s。分母的求和意味着吞吐对长尾样本极其敏感——一条 32K 的样本消耗的产能等于八条 4K 样本。</p>\n<p>推导的关键一步在分桶：若不按长度分桶，一个 batch 的 prefill 计算量按批内最长序列对齐（padding 到 max length），有效 token 占比为 $\\sum L_i / (B \\cdot L_{\\max})$。分桶后同批长度接近，该比值趋近 1，等价于把分母中的 $\\sum L_{\\text{sample}}$ 换成 $\\sum L_{\\text{sample}} \\cdot \\eta$，其中 $\\eta$ 是 padding 浪费系数。这就是为什么分桶不是调度上的锦上添花，而是直接乘在吞吐分母上的因子。分桶粒度的代价是攒批等待：桶越细，同桶样本到齐越慢，队列驻留时间上升，需要在吞吐与回填时延之间取平衡。</p>\n<p>系统代价落在显存与带宽上：奖励模型 prefill 阶段的 KV 只需在单次前向内存活，打分完即可释放，因此奖励服务的 KV 池可以做得比 rollout 引擎小得多，但激活值与权重仍需独立一份。具体例子：奖励服务按 1K/4K/16K/32K 四档分桶，4K 桶攒到 64 条即发，16K 桶攒到 16 条即发，32K 桶攒到 4 条即发——桶内条数随长度递减，是为了让每批的 token 总量大致持平，从而让单批 prefill 时延稳定、队列深度可预测。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-15\">十五 · 队列与回填的伪代码骨架</h3>\n<p>把机制落到可实现层面，核心是三个角色：rollout 生产者、奖励消费者、训练侧回填。生产者只做入队，绝不等待；消费者按桶攒批、打分、带幂等键回填。伪代码思路如下（以文字描述结构，不写代码块）：生产者侧对每条完成的样本生成全局唯一 <code>sample_id</code>，连同 token 序列、长度、策略版本号打包为消息，按长度落入对应桶的待处理队列，入队即返回继续采样；消费者侧循环从各桶取样本，当某桶待处理数达到该桶阈值或等待超时，取出整批做一次 prefill 前向，得到标量 reward 或验证器通过信号，写入结果表并以 <code>sample_id</code> 为键投递回填消息；训练侧维护样本缓冲区，收到回填消息时按 <code>sample_id</code> 查重，若已存在同键结果则丢弃（幂等），否则写入并标记该样本就绪；当就绪样本数达到 batch size，训练侧取走整批启动更新。</p>\n<p>幂等键的设计要点：<code>sample_id</code> 必须由生产者生成且全局唯一，不能由消费者在打分时生成，否则重试会产生新键、破坏去重。故障恢复时消费者从队列重放未确认消息，训练侧靠查重吸收重复。代价是结果表需要保留一段时间的键集合，其内存占用与在途样本数成正比——这是用小内存换正确性的典型取舍。</p>\n<p>系统代价体现在回填时延上：从样本入队到 reward 可被训练侧消费的间隔，由桶等待时间、批 prefill 时间、回填消息传递时间三段构成。桶等待时间在低负载时占主导，因此超时触发攒批是必要的兜底——否则稀疏桶里的长样本会无限期滞留。具体例子：训练侧 batch size 为 256，若某桶超时设为 200ms，则最坏情况下一条样本在桶内等待 200ms 后才进入打分，这段时延必须计入 $T_{\\text{reward}}$ 的预算。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-16\">十六 · 独立 KV 池与权重共享的显存账</h3>\n<p>奖励服务使用独立 KV 池并与 rollout 引擎共享权重存储，这一部署形态的显存账要分开算。权重共享意味着同一份奖励模型权重在存储层只有一份，两个服务通过映射读取，省去重复加载的存储开销与加载时间；但运行时每个服务仍需把权重驻留在自己的显存中（或按需换入），因此<strong>显存占用是两份而非一份</strong>。KV 池独立的意义在于：奖励服务的 KV 生命周期是单次前向，池子按最大批 token 总量配置即可，不与 rollout 引擎的长驻 KV 争抢；若两者共享 KV 池，rollout 的长序列 KV 会挤压奖励服务的批空间，导致奖励侧被迫降批、吞吐下降。</p>\n<p>定量地看，奖励服务显存需求 $\\approx$ 权重显存 $+$ 峰值激活显存 $+$ 单批 KV 显存。其中单批 KV 显存正比于 $\\sum L_{\\text{batch}}$，因此分桶阈值直接决定这部分的上界——桶阈值定得越大，峰值 KV 越高，但吞吐越好。这是显存与吞吐之间的显式 trade-off，应在容量规划时按目标硬件档位反解桶阈值，而不是先定桶再测显存。</p>\n<p>系统代价在小规模集群上最尖锐：策略模型、奖励模型、KV 池三方争抢同一批卡的显存，奖励服务独立占一份权重后总需求上升，弹性伸缩不及时会触发 OOM 或被动降批。具体例子：单卡部署策略模型与奖励模型时，奖励服务若按满批配置 KV，则策略模型的 rollout KV 空间被压缩，decode 阶段可容纳的并发序列数下降，rollout 吞吐反而受损——此时应缩小奖励桶阈值、以略低的奖励吞吐换取 rollout 的空间。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-17\">十七 · 弹性扩缩容的触发判据与失效路径</h3>\n<p>奖励服务按队列深度独立扩缩容，触发判据应取<strong>队列深度与处理速率的组合</strong>而非单一深度阈值。仅看深度会在突发流量下滞后：深度刚爬升时扩容尚未完成，队列已打满并阻塞生产者。更稳的判据是估计排队时延 $\\hat{W} = D / (s - r)$（$D$ 为当前队列深度，$s$ 为当前奖励吞吐，$r$ 为样本到达速率），当 $\\hat{W}$ 超过回填时延预算时触发扩容；当 $\\hat{W}$ 持续低于预算的一半时触发缩容。这个式子在 $s \\to r$ 时发散，正好刻画了吞吐不匹配时队列爆炸的物理事实。</p>\n<p>失效路径有三条，都需在实现中显式处理。其一，奖励服务故障或重启导致队列中样本丢失或重复打分，若回填缺幂等键，训练侧会混入重复 reward 或缺失样本，污染策略更新——对策是生产者侧保留已入队样本的副本直到收到回填确认，消费者侧重放未确认消息。其二，队列深度与两侧吞吐不匹配时奖励服务成为瓶颈，端到端时间退化为和式，异步重叠失效——对策是把 $s/r$ 作为告警指标，并在扩容粒度不足时接受降级：临时缩小桶阈值以提高奖励侧并发批数。其三，弹性伸缩粒度受硬件档位约束，扩容以整卡或整实例为单位，小集群上粒度粗导致要么过配要么欠配——对策是把奖励服务与 rollout 引擎的扩缩容解耦，奖励侧允许更细的实例切分。</p>\n<p>具体例子：队列深度 200、到达速率 40 条/s、当前奖励吞吐 45 条/s 时，$\\hat{W} = 200/5 = 40$s，远超回填预算，应立刻扩容；扩容后 $s$ 升至 80 条/s，$\\hat{W}$ 降至 5s，队列回落。若扩容因粒度限制只能翻倍到 90 条/s，则稳态队列深度收敛在 $r \\cdot W_{\\text{target}}$ 附近，需同步下调桶阈值以提升 $s$ 的有效利用率。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-18\">十八 · 与训练侧 batch 组装的耦合约束</h3>\n<p>训练侧攒够一个 batch 的样本与 reward 后才启动策略更新，这意味着 $T_{\\text{iter}}$ 中的 $T_{\\text{train}}$ 段之前存在一个<strong>整批就绪屏障</strong>：batch 内最慢的一条样本决定训练启动时刻。奖励服务的分桶与超时策略直接影响这个屏障的宽度——桶越细、超时越长，长尾样本的回填越晚，屏障越宽。因此桶策略不能只按奖励侧吞吐最优来定，必须把训练侧 batch 组装的时间约束纳入。</p>\n<p>推导上，设 batch 内样本的回填时延分布为 $W_i$，则训练启动等待为 $\\max_i W_i$。在分桶机制下，$W_i$ 由所属桶的等待与打分时间决定，长样本桶因阈值低而等待短，短样本桶因阈值高而等待长但打分快，两者叠加后的最大值通常出现在中等长度桶——这是分桶设计时容易忽略的非单调性。工程判断是：对 batch 内长度分布做采样统计，把桶阈值按“使各桶的 $W$ 上界接近”来配置，而不是按“使各桶 token 总量接近”。</p>\n<p>系统代价体现在训练侧的 GPU 空转：屏障期间训练卡闲置等待 reward，若屏障宽度占迭代时间的比例上升，整体利用率下降。具体例子：batch 256 条、长度分布跨越 1K 到 32K，若短桶阈值设为 128 条，则短样本需等 128 条到齐才打分，在稀疏流量下等待时间可能超过长样本桶的打分时间，成为屏障的决定项；把短桶阈值降到 32 条并配合超时触发，可把 $\\max_i W_i$ 压下来，代价是短桶的单批 token 量变小、奖励侧吞吐略降。这个取舍应在容量规划阶段用队列仿真确定，而非上线后调参。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-19\">十九 · 流水线重叠的失效边界与幂等代价</h3>\n<p>公式 $T_{\\text{iter}}\\approx\\max(T_{\\text{rollout}},T_{\\text{reward}})$ 只在队列非空且两侧吞吐匹配时成立。设奖励服务吞吐为 $\\text{thr}_{\\text{reward}}$、rollout 产出速率为 $r_{\\text{roll}}$，则队列深度 $Q$ 的稳态条件为 $r_{\\text{roll}}\\le\\text{thr}_{\\text{reward}}$；一旦 $r_{\\text{roll}}&gt;\\text{thr}_{\\text{reward}}$，$Q$ 单调增长，回填时延 $\\tau_{\\text{fill}}\\approx Q/\\text{thr}_{\\text{reward}}$ 线性膨胀，训练侧等不到齐批样本，端到端时间退化为 $T_{\\text{rollout}}+T_{\\text{reward}}$ 之和，异步重叠彻底失效。这就是奖励服务成为瓶颈的判据：不是看单次打分延迟，而是看稳态队列是否收敛。工程上把 $Q$ 的增长率作为扩缩容触发信号，比按 GPU 利用率触发更早、更准。</p>\n<p>故障路径的代价落在幂等设计上。奖励服务重启时队列中未确认的样本要么丢失、要么被重复投递；若回填只带样本内容而不带唯一幂等键，训练侧缓冲区会混入重复 reward 或缺失样本，策略更新梯度被污染且难以察觉。可实现的做法是：rollout 侧为每条样本生成 $(\\,\\text{rollout\\_id},\\text{sample\\_idx}\\,)$ 复合键，奖励服务打分结果携带该键回填，训练侧缓冲区按键入槽、重复写入覆盖而非追加；队列采用至少一次投递加消费端去重，重启后重放未确认消息。伪代码思路为 <code>enqueue(key, tokens); reward = prefill_score(bucket(tokens)); buffer.upsert(key, reward)</code>，其中 <code>upsert</code> 的幂等性是正确性的唯一保证。</p>\n<p>显存侧的边界同样硬。奖励服务独立持有一份权重与独立 KV 池，在小规模集群上与策略模型、rollout KV 池争抢同一批 HBM；弹性伸缩粒度若粗于队列波动周期，扩容来不及则触发 OOM 或被迫降批，降批又进一步压低 $\\text{thr}_{\\text{reward}}$，形成正反馈式的吞吐塌陷。因此规模上限不由单卡算力决定，而由“队列深度可容忍的时延上界 ÷ 单次扩缩容生效时间”决定。分桶攒批虽减少 padding 浪费，但桶边界设置过细会让批组成碎片化、prefill 效率回落，过粗则长序列拖尾拉高整批时延——桶宽本身就是一个需要与 SLO 对齐的调参项。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>奖励吞吐低于 rollout 产出</td><td>迭代时间退化为两者之和</td><td>按队列增长率触发扩容</td></tr><tr><td>重启丢样本/重复打分</td><td>梯度污染、难以定位</td><td>复合幂等键 + upsert 回填</td></tr><tr><td>扩缩容粒度粗于队列波动</td><td>OOM 或降批导致吞吐塌陷</td><td>细粒度弹性 + 预留显存水位</td></tr></tbody></table>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-20\">二十 · 请求形态：变长完整序列的 prefill 打分</h3>\n<p>奖励服务收到的不是流式对话请求，而是策略 rollout 已经闭合的完整 token 序列——一条样本的全部 token 一次性到达，没有 decode 阶段的逐 token 增量。这意味着奖励服务的请求形态在推理系统分类里几乎只有 prefill：输入长度 $L_{\\text{sample}}$ 从几百到数万不等，输出是一个标量 reward 或验证器的通过/拒绝信号，输出长度近似为 1。把这种请求塞进一个为 decode 优化的引擎是浪费：decode 的连续批处理调度器会把宝贵的 KV 预算花在等待单个 token 上，而奖励服务根本不需要自回归生成。</p>\n<p>因此负载配方的第一层是请求分类：奖励服务应被配置为 prefill-only 打分服务，调度器按 chunked prefill 的算力密度而非 decode 的时延敏感度来排批。打分吞吐的形式化表达为</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$</div>\n<p>分母是逐样本 prefill 时间之和，说明吞吐由总 token 量而非样本条数决定。一条 8192 token 的样本与八条 1024 token 的样本在算力账上等价，但在批组成上完全不同：前者只能与同量级的长序列拼批，后者可以凑出高填充率的短批。这就是为什么请求形态必须先按长度分布刻画，再谈并发。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-21\">二十一 · 长度分布决定分桶粒度与 padding 浪费</h3>\n<p>奖励服务的攒批不是先到先服务，而是按序列长度分桶。设桶边界为 $[b_0,b_1,\\dots,b_k]$，同批序列长度接近时，padding 浪费近似为零；若把一条 16k token 的样本与七条 512 token 的样本硬拼一批，短序列会被 pad 到 16k，有效算力利用率跌到个位数百分比。分桶的工程判据是桶内长度方差相对于桶均值的比例：方差大则桶宽应缩小，代价是攒批等待时间上升。</p>\n<p>长度分布本身有形态差异。RLVR 的推理样本往往长度集中、尾部短，分桶容易；RLHF 的开放式生成样本呈长尾分布，少数超长样本会拖住整个桶的攒批窗口。工程上对长尾的处理是设一个溢出桶：超过阈值的样本单独成批、立即提交，不与短样本互相等待。这一策略的代价是溢出桶的批大小常常为 1–2，prefill 效率低，但它保护了主桶的攒批节奏，避免一条长样本把整条队列的时延拉长。分桶参数直接决定回填时延的分布，而回填时延是奖励服务 SLO 的第一指标。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-22\">二十二 · 并发与批大小：队列深度是唯一有效的控制量</h3>\n<p>奖励服务的并发不由请求数决定，而由队列深度与单批 token 预算共同决定。设单批 token 上限为 $B_{\\text{tok}}$，桶内平均长度为 $\\bar{L}$，则批大小 $n \\approx B_{\\text{tok}}/\\bar{L}$。长序列桶的批大小天然小，短序列桶的批大小可以很大——这不是调参问题，是长度分布的算术结果。把批大小当成固定超参去调，在长尾分布上必然一边 OOM 一边欠填充。</p>\n<p>队列深度承担两个职责：一是吸收 rollout 与 reward 两侧的瞬时吞吐抖动，二是作为弹性扩缩容的触发信号。队列深度持续高于高水位，说明奖励侧算力不足，端到端时间开始由 $T_{\\text{reward}}$ 主导；持续低于低水位，说明奖励侧过度配置，独立权重显存被浪费。这里的关键判断是：队列深度不是越大越好。深队列能提高重叠度，但也意味着样本在队列里等待的时间变长，回填时延的尾部被拉长，且故障时丢失的样本更多。队列深度应按回填时延 SLO 反推上限，而不是按显存余量往上堆。</p>\n<p>具体例子：一个以短推理链为主的 RLVR 负载，长度集中在 1k–2k token，单批 token 预算设为能容纳数十条样本，批大小可达数十，prefill 填充率高，奖励服务用少量副本即可跟上 rollout；同一套配置切换到开放式长生成负载，长度中位数跳到 8k 以上且长尾到数十 k，同样的 token 预算只能容纳个位数样本，批大小骤降，若副本数不随队列深度上调，队列迅速积压，重叠失效。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-23\">二十三 · 负载不对时：重叠退化为串行</h3>\n<p>分离式服务的全部收益建立在 $T_{\\text{iter}} \\approx \\max(T_{\\text{rollout}}, T_{\\text{reward}})$ 之上，而这个最大值形式只在两侧吞吐匹配、队列有足够缓冲时成立。一旦奖励侧成为瓶颈，队列被填满，rollout 引擎写完样本后无处可写，只能阻塞等待，端到端时间退化为 $T_{\\text{rollout}} + T_{\\text{reward}}$ 的串行和。这不是性能下降几个百分点的问题，是把分离式架构的收益全部抹掉、还额外付出了跨服务队列与回填的通信开销。</p>\n<p>触发这种退化的负载形态有三类。其一是长度分布突变：训练中期策略开始生成更长的推理链，奖励侧的分桶与批大小配置未随之调整，单批有效 token 数下降，吞吐随之下降。其二是并发爬升快于弹性伸缩粒度：奖励服务的扩缩容以副本为粒度，冷启动要加载独立权重、初始化 KV 池，队列深度信号到实际算力上线之间存在滞后，这段时间里队列只进不出。其三是奖励模型本身变重：验证器从标量打分换成需要多步前向的复杂校验，单样本算力上升，原配置下的副本数不再够用。</p>\n<p>工程上的判别方法是持续观测两个量：队列深度的时间积分与回填时延的分位数。若队列深度单调上升且回填时延尾部持续突破 SLO，说明奖励侧已成瓶颈，此时应优先调分桶与批大小而非盲目加副本——因为批大小欠填充时加副本只是把低效复制了多份。只有在单副本 prefill 已接近其算力上限时，扩副本才是正确动作。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-24\">二十四 · 显存与弹性的耦合：小集群上的负载错配代价</h3>\n<p>奖励服务独立占用一份权重显存与独立 KV 池，这在负载匹配时是干净的隔离，在负载错配时变成显存争抢。小规模集群上，策略模型、rollout 的 KV 池、奖励权重三者共享同一批卡的显存预算；奖励服务按队列深度弹性伸缩，扩副本就要多占一份权重，缩副本释放得慢则留下碎片。弹性不及时的后果不是性能问题而是可用性问题：显存不足触发 OOM 或调度器被动降批，而降批又进一步降低奖励吞吐，形成正反馈式的恶化。</p>\n<p>负载配方在这里的约束是：奖励服务的副本数上限必须由集群剩余显存而非队列深度单独决定，扩缩容策略要带显存水位的前置校验。对长序列负载尤其如此——长序列桶的 KV 池占用远高于短序列桶，同样副本数下显存需求可能翻倍，按短序列负载标定的副本上限在长序列负载下会直接撞墙。可行的做法是把 KV 池按桶类型分区，长序列桶使用受限配额的 KV 池，超出配额的样本排队等待而非抢占短序列桶的资源，用可控的排队换取不 OOM。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-25\">二十五 · 幂等与负载配方的交叉约束</h3>\n<p>负载不对时还有一个隐性代价：队列积压与弹性伸缩会放大故障窗口。奖励服务重启时队列中的样本若未持久化，回填缺失；若队列做了重放，同一样本可能被打分两次。负载配方因此必须与幂等键设计绑定：每个样本携带唯一 id，回填侧按 id 去重，重复打分的结果丢弃而非覆盖。在队列深度大、副本频繁伸缩的负载下，重复打分概率上升，幂等键从“防御性设计”变成“常态路径”。</p>\n<p>这条约束反过来限制了批大小的激进程度：批越大，单次故障影响的样本越多，重放与去重的成本越高。因此负载配方的最终形态是一个三元折中——分桶粒度决定填充率，批大小决定单批风险敞口，队列深度决定重叠度与故障暴露面。三者不能各自独立调优，必须按同一套 SLO（打分吞吐、回填时延分位数、故障后恢复时间）联合标定。当负载形态偏离标定点时，先动分桶与队列深度，再动批大小，最后才动副本数——这个顺序保证每次调整都在修正瓶颈而不是复制低效。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-26\">二十六 · 负载配方：变长 prefill 打分与队列深度决定重叠成败</h3>\n<p>奖励分离式服务的负载画像与策略 rollout 截然不同：请求形态是<strong>变长的完整序列 prefill 打分</strong>，没有自回归 decode 阶段，每条样本一次性喂入整段 token，输出仅一个标量 reward 或验证器通过信号。这意味着奖励服务的算力几乎全部压在 prefill 上，其吞吐由公式 <span class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$</span> 刻画——分母是各样本长度除以奖励模型 prefill 速率的累加，序列越长、方差越大，单位时间能打分的样本数越低。因此负载配方第一条就是长度分布：短样本密集（如短问答、分类式验证器）时奖励服务轻松跟上 rollout；长序列密集（长思维链、长文档核验）时 prefill 成本线性膨胀，奖励侧极易成为瓶颈。批大小必须按长度分桶后攒批，让同批序列长度接近，减少 padding 浪费，否则一条超长样本会把整批的有效算力拖垮。</p>\n<p>第二条是并发与队列深度。队列是 rollout 与奖励两侧解耦的唯一缓冲，深度直接决定重叠程度：深度足够时，rollout 生成第 k+1 批的同时奖励服务消化第 k 批，端到端迭代时间趋近 <span class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{rollout}},\\ T_{\\text{reward}}) + T_{\\text{train}}$$</span>；一旦队列被填满或长期空转，两侧吞吐不匹配，重叠失效，时间退化为 <span class=\"formula\">$$T_{\\text{rollout}} + T_{\\text{reward}} + T_{\\text{train}}$$</span> 的串行和。SLO 应以<strong>打分吞吐与回填时延</strong>双指标衡量：吞吐决定训练侧能否攒够 batch，回填时延决定样本缓冲区等待时长。弹性扩缩容的触发点也应挂在队列深度上，而非 GPU 利用率——prefill 型负载的利用率曲线在攒批间隙会剧烈抖动，用利用率做伸缩信号会误判。</p>\n<p>负载不对时的失效模式有三类，且都带明确系统代价。<strong>其一，吞吐失配</strong>：奖励服务持续满队列而 rollout 侧空闲，端到端时间被奖励侧钉死，GPU 利用率在策略侧塌陷，等价于为一份独立权重显存付了钱却只买到串行流水线。<strong>其二，长度分布漂移</strong>：训练中后期策略输出变长（思维链自我扩展是典型），奖励侧 prefill 成本随之上升，原本匹配的批大小与并行拓扑失效，需重新分桶与调批，否则单批延迟拉长、回填时延突破 SLO。<strong>其三，故障与幂等</strong>：奖励服务重启时队列中的样本丢失或重复打分，若回填缺少幂等键，训练侧会混入重复 reward 或缺失样本，污染策略更新——这不是性能问题而是正确性问题，代价是整批训练数据作废重跑。</p>\n<p>边界判断可落在一张小表上：适合的负载是<strong>长度中短且分布集中、rollout 吞吐显著高于奖励 prefill 吞吐、集群规模足以容纳独立权重显存</strong>；不适合的是超长序列密集、奖励模型与策略模型体量相当（独立权重显存翻倍直接挤压 KV 池）、以及弹性伸缩粒度粗于队列波动周期的场景——此时扩缩容来不及，OOM 或降批先于扩容发生。工程上应把队列深度、分桶粒度、幂等键三者作为同一套配置一起调，任何一项缺失都会让“最大值重叠”退化为“串行相加”。</p>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-27\">二十七 · 硬件档位：按奖励模型的 prefill 形态选卡，而不是按策略模型选卡</h3>\n<p>奖励服务与 rollout 引擎的硬件选型逻辑并不相同。rollout 引擎的负载是自回归解码，瓶颈在逐 token 的权重读取与 KV 追加，对单卡带宽与低延迟敏感；奖励服务做的是对一条完整长序列的一次性 prefill 打分，瓶颈在矩阵乘的算力密度与长序列的 attention 展开。因此部署配方的第一条判断是：奖励服务不应继承策略模型的卡型与切分方式，而应按自身 prefill 吞吐重新选档。在 Blackwell 上，SM100 的 B200 单卡提供完整的 tcgen05 张量核心路径与 TMEM，适合把奖励模型的 prefill 压到高算力利用率；若奖励模型本身较小（例如基于 7B–13B 的标量头或分类头验证器），则 GB200 NVL72 机柜内的单节点多卡更划算，因为奖励服务需要的是“多卡并行摊薄单条长序列的 prefill 时延”，而不是“单卡塞下整个模型”。</p>\n<p>档位选择要落在一个可算的判据上。设奖励服务的目标是让打分吞吐匹配 rollout 产出速率，则单卡可承载的样本速率近似为：</p>\n<div class=\"formula\">$$\\text{rate}_{\\text{card}} \\approx \\frac{\\text{thr}_{\\text{reward\\_prefill}}}{L_{\\text{sample}}},\\quad N_{\\text{card}} \\ge \\left\\lceil \\frac{N_{\\text{samples}}/T_{\\text{rollout}}}{\\text{rate}_{\\text{card}}} \\right\\rceil$$</div>\n<p>其中 $L_{\\text{sample}}$ 是分桶后的平均序列长度，$\\text{thr}_{\\text{reward\\_prefill}}$ 是该卡在目标精度下的 prefill token 吞吐。这个式子的工程含义是：奖励服务的卡数由 rollout 的样本产出速率除以单卡打分速率决定，而不是由奖励模型参数量除以单卡显存决定。举例：一个 RLVR 任务每轮 rollout 产出数千条长度在数千 token 量级的样本，若单卡 prefill 吞吐按每轮打分时间折算后只能覆盖其中一部分，则必须横向加卡；反之若奖励模型很小而序列很短，加卡只会让分桶攒批的批大小被切碎，反而降低单卡利用率。</p>\n<p>代价面必须写清：奖励服务独立占一份权重显存，意味着集群总显存需求上升。在小规模集群上，这份额外权重会与策略模型权重、rollout 的 KV 池争抢同一批 HBM，弹性伸缩不及时就会触发 OOM 或被迫降批。因此档位配方里要预留一块“奖励服务专用显存预算”，并在容量规划时把它当作固定开销而非可压缩项。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-28\">二十八 · 并行拓扑：TP 沿序列维摊薄时延，PP 不适用于打分</h3>\n<p>奖励服务的并行拓扑应按 prefill 的并行性来设计。prefill 阶段一条长序列的 attention 与 MLP 都可以在序列维切分，因此张量并行（TP）是首选：把权重按 hidden 维切开，多卡同时处理同一批序列的不同分片，单条样本的打分时延随 TP 度近似下降，而吞吐随卡数上升。相比之下，流水并行（PP）在奖励服务里几乎无收益——PP 的收益来自把多层模型分段以容纳显存，代价是 microbatch 之间的流水气泡；而奖励服务做的是单次前向打分，没有解码那样的长序列迭代来摊薄气泡，PP 只会引入额外的激活传输与同步。</p>\n<p>拓扑配方还要处理“分桶攒批”与“并行度”的耦合。奖励服务按序列长度分桶后攒批，同批序列长度接近，padding 浪费小；但如果 TP 度过高，单卡上的批被切得太小，矩阵乘的 M 维不足以喂满张量核心，算力利用率反而下降。一个可复现的判断是：先固定 TP 度使单条最长序列的 prefill 时延满足回填时延 SLO，再在该 TP 度下把分桶批大小调到让单卡 M 维达到有效区间。对 2-SM MMA 路径，批的 M 维与 tile 形状要匹配，否则 tcgen05 的利用率会掉。</p>\n<p>具体例子：奖励模型为一个带标量头的 13B 验证器，序列长度分布在数千 token。若用 TP=4 部署在单节点四卡上，每条样本的 prefill 被切成四份并行，回填时延可控；若改用 PP=4，则每张卡只承载部分层，单条样本仍要串行穿过四段，时延不降反升，且段间激活传输占用 NVLink 带宽。工程结论是：奖励服务的拓扑以 TP 为主，必要时叠加 DP（数据并行）来扩吞吐——DP 副本各自持有完整权重与独立 KV 池，按队列深度分流，这也是弹性扩缩容的粒度单位。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-29\">二十九 · 量化方案：奖励打分对数值误差的容忍度低于生成</h3>\n<p>量化配方不能照抄 rollout 引擎。生成任务里，低精度带来的微小 logit 扰动通常被采样过程吸收；而奖励模型输出的是用于策略更新的标量 reward 或验证器通过信号，这个标量直接进入优势估计与梯度，误差会被放大到训练稳定性上。因此在奖励服务上，量化方案要分层：权重可以用 FP8 甚至 NVFP4 存储以省显存、提 prefill 吞吐，但打分头的最后一层与归一化路径应保留较高精度，避免标量输出被量化噪声主导。这与 NVFP4 在 rollout 上的稳定化是两条不同的路径——后者关心的是生成分布不被量化扭曲，前者关心的是标量信号的保真。</p>\n<p>一个可操作的配方是：奖励模型主干用 FP8 权重 + FP8 激活做 prefill，打分头用 BF16 计算；若显存紧张需要上 NVFP4，则对主干做块级缩放量化，并对打分头保留 BF16，同时在服务侧记录量化前后 reward 的偏差分布作为监控项。代价是混合精度路径会引入额外的类型转换与部分高精度算子，prefill 吞吐相比全 FP8 有折损，但换来的是训练侧不会因为 reward 抖动而反复回滚。</p>\n<p>量化与 KV 策略要一起看。奖励服务做的是单次 prefill 打分，理论上不需要跨请求保留 KV——每条样本打分完成后其 KV 即可释放。因此奖励服务的 KV 池应按“峰值并发批的序列总长度”来分配，而不是按长驻缓存来分配。这与 rollout 引擎需要长期持有前缀 KV 的形态完全不同。配方上，奖励服务使用独立 KV 池、按分桶批的即时需求分配、打分后立即回收，可以把 KV 显存压到很小，把省下的显存让给更大的分桶批或更高的 TP 度。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-30\">三十 · KV 策略与权重存储共享：独立池、共享盘</h3>\n<p>部署配方里最容易出错的一处是权重存储。奖励服务与 rollout 引擎共享权重存储（同一份模型权重的落盘副本或同一权重分发通道），但运行时各自持有独立的权重副本与独立 KV 池。共享存储的意义在于：奖励模型与策略模型若同源或共享主干，可以避免重复落盘与重复传输；独立运行时副本的意义在于：两侧的并行切分不同（rollout 可能按解码优化切分，奖励按 prefill 的 TP 切分），权重布局不能直接复用，必须各自加载成匹配自身拓扑的分片。</p>\n<p>KV 策略的具体机制是“打分即释放”。奖励服务收到一条样本，按其长度归入对应桶，攒批后做一次 prefill，attention 的 KV 只在本次前向内存在，输出标量后整批 KV 归还池。这样 KV 池的容量需求近似为：</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{reward}} \\approx B_{\\text{peak}} \\cdot L_{\\text{bucket}} \\cdot d_{\\text{kv}} \\cdot \\text{bytes}$$</div>\n<p>其中 $B_{\\text{peak}}$ 是峰值并发批大小，$L_{\\text{bucket}}$ 是该桶的代表长度，$d_{\\text{kv}}$ 是每 token 的 KV 维度。由于 $B_{\\text{peak}}$ 由分桶攒批策略控制，KV 显存成为一个可调的调度参数而非固定开销。代价是：如果队列深度突增导致攒批变大，KV 池会瞬时吃紧，需要调度器在攒批上限与 KV 容量之间做约束，否则会触发 OOM 或被迫拆批，拆批又会让 padding 浪费回升。</p>\n<p>具体例子：一个验证器服务按长度分成短、中、长三个桶，长桶的单条序列 KV 占用显著高于短桶。若调度器把长桶的攒批上限设得过高，KV 池会被长桶独占，短桶请求排队等待，回填时延抖动。配方上应给每个桶独立的攒批上限与 KV 配额，让长短桶互不挤占。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-31\">三十一 · 调度参数：队列深度是弹性扩缩容的唯一触发量</h3>\n<p>调度参数的核心是队列深度。奖励服务的扩缩容触发点由队列深度决定，而不是由 GPU 利用率决定——因为奖励服务的负载是突发且分桶的，GPU 利用率在攒批间隙会短暂回落，用它做触发会误缩容。队列深度直接反映“rollout 产出速率与奖励打分速率之差”的累积，是两侧吞吐是否匹配的显式信号。当队列深度持续上升，说明奖励服务成为瓶颈，端到端迭代时间从 $\\max(T_{\\text{rollout}}, T_{\\text{reward}})$ 退化为两者之和，异步重叠失效；此时应扩容 DP 副本或提高单副本的攒批上限。</p>\n<p>调度参数还包括回填时延 SLO 与幂等键。回填按样本 id 进行，每条样本在进入队列时分配唯一幂等键，奖励服务输出结果时携带该键，训练侧按键去重回填。这样在奖励服务故障或重启时，队列中丢失的样本可以被重新提交，重复打分的样本会被去重，避免训练侧混入重复 reward 或缺失样本。代价是幂等键的维护需要队列与训练侧样本缓冲区之间的一致性协议，故障恢复时要做一次队列重放与去重扫描，这段时间奖励服务不产出新结果，回填时延会短暂抬升。</p>\n<p>一个可复现的配置思路可以写成如下伪代码式的参数表：</p>\n<ul>\n<li>硬件档位：按 $\\text{rate}_{\\text{card}}$ 与 rollout 产出速率算卡数，奖励服务单独预留显存预算。</li>\n<li>并行拓扑：TP 沿序列维摊薄单条时延，DP 副本按队列深度扩缩容，不用 PP。</li>\n<li>量化：主干 FP8/NVFP4 权重，打分头 BF16，监控 reward 偏差。</li>\n<li>KV：独立池、按桶配额、打分即释放，攒批上限受 KV 容量约束。</li>\n<li>调度：队列深度触发扩缩容，幂等键去重回填，回填时延 SLO 作为攒批上限的约束。</li>\n</ul>\n<p>这套参数的验证方式是看端到端迭代时间是否稳定在 $\\max(T_{\\text{rollout}}, T_{\\text{reward}})$ 附近：若实测接近两者之和，说明队列深度与两侧吞吐不匹配，应先调攒批上限与 DP 副本数，再考虑换硬件档位。工程判断落在队列深度这一个量上——它是奖励服务是否值得独立部署、独立扩缩容的直接证据，也是这套分离式服务在小集群上是否划算的边界条件。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-32\">三十二 · 奖励服务的部署配方边界：分桶攒批的收益何时被队列与显存吃掉</h3>\n<p>奖励服务独立部署的配置思路可以按“先定并行拓扑，再定量化与 KV，最后用队列深度反推扩缩容粒度”的顺序落地。并行拓扑按奖励模型自身的 prefill 最优形态选择：奖励打分是纯 prefill、无自回归 decode，因此 TP 只需满足单卡权重放得下并让每卡 prefill 算力吃满，不必为低延迟 decode 留出过多 TP 度；序列长度分桶后同批长度接近，padding 浪费被压到很小，长序列打分应优先走大 batch 而非大 TP。量化上奖励模型对数值误差的容忍度低于策略模型——reward 是标量输出，NVFP4 的量化噪声会直接进入训练信号，因此权重可用 FP8、打分头与归一化层保留高精度，验证器若输出的是通过/拒绝的离散信号则可放宽到更低精度。KV 策略是这套配方里最容易被忽视的一项：奖励服务只做一次前向 prefill，KV 在打分完成后即可释放，独立 KV 池应按“在飞批次数 × 单批最长序列”估算而非按常驻会话估算，池子开得过大反而挤压权重显存。</p>\n<p>吞吐与迭代时间的关系决定了配方的失效边界。打分吞吐可写成</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$</div>\n<p>即吞吐由总 token 量与 prefill 速率之比决定，分桶只减少 padding、不改变分子。端到端迭代时间 $T_{\\text{iter}} \\approx \\max(T_{\\text{rollout}}, T_{\\text{reward}}) + T_{\\text{train}}$ 成立的前提是队列深度足够吸收两侧的瞬时抖动：当 rollout 突发产出速率超过奖励服务稳态吞吐，队列被填满后 rollout 侧写入被阻塞，重叠失效，$T_{\\text{iter}}$ 退化为两者之和。因此队列深度不是越大越好，它同时是弹性扩缩容的触发信号——深度持续超过阈值即扩容，持续低于阈值即缩容，扩缩容粒度必须小于单批打分时间，否则一次扩容来不及在瓶颈窗口内生效。</p>\n<table class=\"mini\"><thead><tr><th>配置项</th><th>取值取向</th><th>失效条件</th></tr></thead><tbody><tr><td>并行拓扑</td><td>按 prefill 最优，TP 最小化</td><td>TP 过大导致单批 token 数不足，算力闲置</td></tr><tr><td>量化</td><td>权重 FP8，打分头高精度</td><td>NVFP4 用于标量输出，reward 噪声进入训练</td></tr><tr><td>KV 池</td><td>按在飞批次估算，打分后释放</td><td>按常驻会话估算，挤压权重显存</td></tr><tr><td>队列深度</td><td>覆盖单批打分时间的抖动</td><td>过深掩盖瓶颈，过浅使 rollout 阻塞</td></tr></tbody></table>\n<p>显存是这套配方在小规模集群上的硬约束：奖励服务独立占用一份权重，与策略模型、rollout 的 KV 池争抢同一批卡的显存，弹性伸缩不及时会直接触发 OOM 或被动降批，而降批又反过来拉低打分吞吐、加深队列积压，形成正反馈。工程判断是：当奖励模型权重占单卡显存的比例高到无法与 rollout 共享同一批卡时，应把奖励服务放到独立卡组而非依赖弹性伸缩；同时回填路径必须带样本 id 作为幂等键，奖励服务重启后队列中的在飞样本要么重打分要么丢弃，缺少幂等键会让训练侧混入重复 reward 或缺失样本，这类错误不会报错，只会以策略更新方差变大的形式隐性出现。</p>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-33\">三十三 · 显存：独立权重是固定开销，KV 池才是弹性变量</h3>\n<p>奖励服务拆出去之后，显存账本要分成两块看。第一块是奖励模型权重本身，它是常数项：无论队列里排着 1 条还是 10000 条样本，这份权重都常驻在卡上。第二块是打分时的 KV 池，它是变量项，随攒批大小和序列长度线性增长。工程上真正容易翻车的是把这两块混在一起做容量规划——按平均队列深度算出一个“够用”的显存预算，然后在队列尖峰时被 KV 池撑爆。</p>\n<p>设奖励服务单卡可用显存为 $M$，权重占用 $W_r$，每 token 的 KV 开销为 $k$ 字节、层数为 $L$、并发序列数为 $B$、平均序列长度为 $\\bar{S}$，则可行条件为：</p>\n<div class=\"formula\">$$W_r + B\\cdot \\bar{S}\\cdot L\\cdot k \\le M\\cdot(1-\\epsilon)$$</div>\n<p>其中 $\\epsilon$ 留给激活值与临时缓冲。这个不等式说明：一旦 $W_r$ 吃掉大半显存，$B$ 的上限就被压得很低，而 $B$ 恰恰是 prefill 打分吞吐的来源。奖励模型往往比策略模型小一个量级，但小模型不等于小显存压力——KV 池按序列长度算，奖励输入是完整长序列，$\\bar{S}$ 比 rollout 侧的 decode 阶段大得多。代价直接体现在吞吐上：$B$ 掉一半，prefill 的有效算力利用率跟着掉，因为单条长序列的 prefill 很难把 SM 喂满。</p>\n<p>具体例子：一个 7B 级奖励模型在单卡上权重占去可观份额，剩余显存按长序列 KV 折算只够容纳个位数并发；若队列里堆着数千条待打分样本，服务只能小批慢跑，此时扩容粒度若是一整卡，就会出现“加了一张卡但队列深度只降了一点”的尴尬——因为新卡的权重又复制了一份。这就是小模型集群上总显存需求上升的机制根源：不是模型大，是权重副本数随并行度线性增加。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-34\">三十四 · 带宽：prefill 打分是访存受限，不是算力受限</h3>\n<p>奖励服务的负载形态是纯 prefill：输入完整序列、输出一个标量。这类负载的算术强度极低——每个 token 过一遍权重矩阵，最后只产生一个 reward 值，中间的所有激活都是过路数据。因此瓶颈通常不在 tensor core 的 FLOPS，而在 HBM 带宽与权重读取次数。攒批的意义正在于此：批内序列共享同一次权重读取，把“每 token 一次权重搬运”摊薄成“每批一次”。</p>\n<p>用 $N_{\\text{samples}}$ 条样本、总 token 数 $\\sum L_{\\text{sample}}$、奖励服务 prefill 吞吐 $\\text{thr}_{\\text{reward\\_prefill}}$（token/s）表达，打分吞吐为：</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}}$$</div>\n<p>注意分母是总 token 时间，分子是样本数——这意味着吞吐的分子端由“每条样本多长”决定。序列越长，单位时间打出的样本数越少，而队列积压速度不变，于是队列深度单调上升。带宽代价的具体表现是：当批大小不足以摊薄权重读取时，HBM 带宽被打满而 SM 利用率很低，此时增加并发反而改善吞吐；一旦批大到权重读取已充分摊薄，再加大批只会增加 KV 池压力而不提速。工程判断的落点就在这里——分桶攒批的目标不是“批越大越好”，而是把批推到带宽拐点附近，让 $\\text{thr}_{\\text{reward\\_prefill}}$ 接近饱和而 KV 池不溢出。</p>\n<p>具体例子：长度分桶后，短序列桶可以攒很大的批，长序列桶只能攒很小的批。如果服务用一个全局批大小配置，短桶浪费显存、长桶打不满带宽。按桶独立设批上限，是让带宽利用率在两类桶上都接近拐点的直接手段。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-35\">三十五 · 通信：队列传输量小，但回填路径的时延不可忽略</h3>\n<p>奖励分离式服务的跨进程通信有两个方向。上行是 token 序列与元数据，下行是标量 reward 或验证器通过信号。上行数据量看似可观——完整序列的 token id 加元数据，但相对于同规模张量的 AllReduce 而言很小；下行更是每条样本几个字节。所以通信带宽通常不是首要瓶颈，真正的代价在时延结构上。</p>\n<p>上行路径的时延由“入队—攒批—调度”三段组成。攒批等待是主动引入的延迟：为了让批足够大以摊薄权重读取，服务必须等，而等待时间直接加到单条样本的打分时延上。这就是尾延迟的第一个来源——短序列样本可能等很久才凑进一个批，它的端到端时延由攒批窗口而非计算时间决定。下行回填路径的时延则取决于训练侧缓冲区的轮询或事件通知机制，若回填是批量拉取而非逐条推送，单条样本的 reward 可见时间会被拉到下一个拉取周期。</p>\n<p>具体例子：一条很短的验证样本进了长序列桶，攒批窗口内迟迟凑不满批，它的打分计算只花极短时间，但排队等待占去绝大部分时延。若训练侧的 batch 组装恰好卡在这条样本上，整个策略更新就被一条短样本拖住。缓解手段是按桶设不同的攒批超时——长桶容忍更长等待，短桶超时后立即以欠批状态发射，用少量带宽损失换尾延迟。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-36\">三十六 · 功耗与弹性：扩缩容粒度决定规模上限</h3>\n<p>奖励服务的功耗特征是“峰值高、占空比随队列波动”。prefill 打分是短时高功率段，队列空了之后服务进入低功率待机。这种波动对集群功耗预算不友好：按峰值配置功耗额度，队列低谷时额度闲置；按均值配置，尖峰时触发功率封顶而降频，反过来拉长打分时间、加深队列积压，形成正反馈。</p>\n<p>弹性伸缩的粒度是规模上限的直接约束。若扩容单位是一整卡或一整节点，那么队列深度从 1.5 倍涨到 2 倍时，服务要么不动（欠配）要么翻倍（过配），中间没有细粒度。过配的代价是权重副本多复制一份、显存与功耗额度被闲置占用；欠配的代价是队列持续积压，端到端迭代时间从 $\\max(T_{\\text{rollout}}, T_{\\text{reward}})$ 退化为两者之和，异步重叠彻底失效。这个退化不是渐变而是跳变：一旦 $T_{\\text{reward}}$ 超过 $T_{\\text{rollout}}$ 并持续，rollout 侧每产出一批就被队列堵住，流水线从重叠态滑入串行态。</p>\n<p>具体例子：队列深度监控若只在分钟级采样，一次突发的大量长序列样本可能在两个采样点之间把队列推高数倍，而扩缩容决策要等到下一个采样周期，期间服务以原并行度硬扛，尾延迟飙升。把扩缩容触发点绑到队列深度的一阶差分而非绝对值，能提前半个周期动作。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-37\">三十七 · 规模上去以后哪里先崩</h3>\n<p>把上述四类代价按规模排序，崩溃顺序是有规律的。第一崩的是尾延迟，不是吞吐：队列深度与两侧吞吐不匹配时，单条样本的攒批等待先恶化，P99 时延在吞吐指标还好看的时候就已失控。第二崩的是显存，因为权重副本随并行度线性增长，而 KV 池随队列尖峰瞬时膨胀，两者叠加在小集群上先触发 OOM 或被动降批。第三崩的是弹性粒度，队列深度的波动幅度超过扩缩容单位所能吸收的范围，服务在欠配与过配之间震荡。功耗封顶通常最后才成为硬约束，但它一旦触发就会反过来加剧前三个问题。</p>\n<p>对应的工程判断是：容量规划不能只按平均吞吐做，必须按“队列深度分布的上分位 + 攒批超时”反推所需并发与显存；扩缩容要按桶分别监控，长序列桶的积压比总队列深度更能预测崩溃点；幂等键必须在回填路径上从第一天就带上，因为故障重启与重复打分在规模上去之后是常态而非异常。奖励服务与 rollout 引擎共享权重存储但使用独立 KV 池这一部署形态，决定了权重副本是可控的、KV 池是必须逐桶核算的——把弹性预算花在 KV 池上，比花在多加一份权重副本上更划算。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-38\">三十八 · 奖励服务先崩在哪：队列深度、显存配额与回填幂等</h3>\n<p>分离式奖励服务把端到端迭代时间从“和”改写为“最大值”，但这个改写只在两侧吞吐匹配、队列深度足够的窗口内成立。设奖励服务按长度分桶后的单批打分吞吐为 $\\text{thr}_{\\text{reward\\_prefill}}$（token/s），样本集总长度为 $\\sum L_{\\text{sample}}$，则打分侧的理论吞吐为 $\\text{throughput}_{\\text{reward}} = N_{\\text{samples}} / (\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}})$。一旦 rollout 侧的样本产出速率超过该值，队列单调增长，$T_{\\text{iter}}$ 退化为 $T_{\\text{rollout}} + T_{\\text{reward}}$ 的串行形态——异步重叠在数学上失效，而不是“变慢一点”。这是规模上去后第一个崩点：不是算力不够，而是两侧速率失配导致流水线语义被破坏。工程上必须把队列深度与两侧吞吐比作为一等监控指标，队列持续增长即触发奖励侧扩容或 rollout 侧降速，而不是等尾延迟爆表再反应。</p>\n<p>第二个崩点是显存配额。奖励服务独立占用一份权重显存并使用独立 KV 池，与 rollout 引擎只共享权重存储。在小规模集群上，这份额外权重与策略模型权重、rollout 的 KV 池三方争抢同一批 HBM：奖励模型虽小，但其输入是完整长序列，prefill 阶段的激活与 KV 峰值按序列长度线性抬升，分桶攒批又会把同批序列长度推高，单批显存占用随之上升。弹性伸缩不及时的直接后果是 OOM 或被迫降批，而降批又反过来压低 $\\text{thr}_{\\text{reward\\_prefill}}$，把系统推回第一个崩点。因此扩容触发点应绑定队列深度与单批显存水位两个信号，而非仅看 GPU 利用率。</p>\n<p>第三个崩点是通信与回填路径。token 序列与元数据经队列送入奖励服务，标量 reward 或验证器通过信号按样本 id 回填训练侧缓冲区，这条路径的带宽开销与样本长度成正比，长序列场景下队列本身的序列化与传输不可忽略；更关键的是幂等性。奖励服务故障或重启时，队列中在途样本会丢失或重复打分，若回填缺少幂等键，训练侧会混入重复 reward 或缺失样本，策略更新被污染且难以事后定位。正确做法是样本 id 作为幂等键、回填侧做去重与缺失检测，奖励服务重启后从队列持久化点重放，而不是简单重投。</p>\n<table class=\"mini\"><thead><tr><th>崩点</th><th>触发条件</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>吞吐失配</td><td>rollout 产出速率 &gt; $\\text{throughput}_{\\text{reward}}$</td><td>端到端时间退化为两者之和，尾延迟抬升</td><td>队列深度驱动扩容，两侧速率比监控</td></tr><tr><td>显存争抢</td><td>小集群三方共享 HBM，长序列攒批抬高激活峰值</td><td>OOM 或降批，打分吞吐下降</td><td>独立 KV 池配额、显存水位触发伸缩</td></tr><tr><td>回填非幂等</td><td>奖励服务重启、队列在途样本丢失</td><td>重复 reward 或缺失样本污染训练</td><td>样本 id 幂等键、持久化重放</td></tr></tbody></table>\n<p>功耗维度上，奖励服务的 prefill 打分是计算密集但访存相对规整的负载，与 rollout 的 decode 阶段功耗特征不同；两侧同卡混部时功耗峰值叠加会压缩频率余量，分离部署后各自按最优 prefill 配置选型，反而使功耗曲线更可预测——但代价是整机功耗预算需按两套服务之和规划，小集群上这是实打实的容量成本。规模上限因此不在单卡算力，而在队列深度与弹性伸缩粒度：伸缩粒度过粗，扩容滞后于队列增长；过细，权重加载与 KV 池重建的开销吃掉重叠收益。</p>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-39\">三十九 · 精度漂移：从打分标量到训练信号的失真链</h3>\n<p>奖励服务与策略服务分离后，最隐蔽的失败不是崩溃，而是“看起来正常”的精度漂移。奖励模型在独立服务里按自身最优 prefill 配置运行，其数值路径（量化档位、归约顺序、KV 池布局）与训练侧历史基线不一致时，同一 token 序列的打分会出现系统性偏移。这种偏移不触发任何异常，却直接污染优势估计：奖励标量的微小偏差经归一化后被放大成策略梯度的方向性错误。</p>\n<p>诊断的关键是把标量比对升级为分布比对。对同一批固定样本（锚定集）周期性重放打分，记录 reward 的均值、方差与分位点，与基线做 KS 检验；同时保留打分时的输入摘要（token 数、桶号、批内邻居数），因为分桶改变了批组成，而归约顺序随批形状变化。工程上给每条 reward 附带一个数值指纹：<div class=\"formula\">$$\\delta = \\left| \\frac{r_{\\text{now}} - r_{\\text{base}}}{\\max(|r_{\\text{base}}|, \\epsilon)} \\right|$$</div>当 $\\delta$ 的 P99 越过阈值即冻结回填、切回上一版数值配置。代价是锚定集重放占用奖励服务约一个桶的 prefill 容量，属于吞吐税；但相比污染一整轮策略更新，这笔税必须付。具体例子：验证器服务从高精度归约切到低精度累加后，通过率在长序列上整体上移，若不比对分布，训练侧只会看到“策略突然变好”的假信号。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-40\">四十 · OOM 与降批：显存争抢的三种触发路径</h3>\n<p>奖励服务独立占一份权重显存，这在中小规模集群上直接把总显存需求推高。OOM 有三条路径：其一，队列积压触发弹性扩容，新副本拉起时与既有副本、rollout 引擎的 KV 池争抢同一批卡；其二，分桶攒批时某桶序列异常长，padding 与激活峰值超出预估；其三，权重存储共享但 KV 池独立，权重换页与 KV 分配在同一 HBM 上叠加。</p>\n<p>监控不能只看显存占用率，要看“批形状—显存峰值”的映射关系。奖励服务应按桶记录每批的 token 总数与峰值显存，拟合出安全边界；调度器在攒批时以 token 总数为约束而非样本数为约束，超界即拆批。降批是最后手段：当队列深度超过阈值而扩容不可用时，主动把批大小压到安全区，用吞吐换稳定。代价明确——降批直接抬高 $\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}$ 的分母效率损失，打分吞吐下降，端到端迭代时间向 $T_{\\text{reward}}$ 一侧倾斜。具体例子：长序列验证任务在桶内出现单条超长样本时，按样本数攒批会瞬间打爆显存；改为按 token 预算攒批后，同一队列深度下峰值显存可控，代价是短序列批被拆细、prefill 效率略降。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-41\">四十一 · 批抖动与路由不均：异步重叠失效的两个前兆</h3>\n<p>批抖动的本质是队列深度振荡：rollout 侧突发产出一大批样本，奖励服务攒批—打分—回填的节拍被打乱，批大小在“撑爆”与“饿死”之间来回。抖动本身不致命，致命的是它与路由不均叠加。多副本奖励服务若按简单轮询或按连接数分发，长序列会集中到某几个副本，短序列副本空转，全局吞吐被最慢副本钉死。</p>\n<p>诊断批抖动看两个量：队列深度的方差，以及批大小分布的熵。方差持续偏高说明两侧吞吐不匹配，异步重叠正在退化——端到端时间从 $\\max(T_{\\text{rollout}}, T_{\\text{reward}})$ 滑向两者之和，这是分离式服务最核心的收益流失。路由不均则看副本间的桶分布与打分时延分位点：若某副本的 P99 时延显著高于同批其他副本，且其桶内长序列占比偏高，即为路由偏斜。修法是按长度感知路由——队列入口先读序列长度，把长序列定向到预分配了大 KV 池的副本，短序列走轻量副本。代价是路由层增加一次元数据查询与转发跳数，回填时延增加一个网络往返；但换来的是副本间负载均衡，尾延迟收敛。具体例子：验证器集群三副本，轮询路由下长序列副本持续积压，短序列副本利用率不足一半；改为长度感知路由后，各副本桶分布接近，队列深度方差下降，端到端迭代时间重新由最大值决定。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-42\">四十二 · 尾延迟尖刺：从 P99 回溯到具体机制</h3>\n<p>尾延迟尖刺在分离式奖励服务里有固定来源：攒批等待、桶边界跨界、回填队列拥塞、以及扩容冷启动。攒批等待是设计使然——为了 prefill 效率必须等批攒够，等待时间随队列深度波动；桶边界跨界发生在一条样本长度刚好落在两桶之间，被反复挪动；回填拥塞是训练侧样本缓冲区写入慢于打分产出；冷启动则是弹性扩容拉起新副本时权重加载与 KV 池初始化占用的时间。</p>\n<p>定位尖刺不能只看服务端时延，要拆成三段打点：入队到出队（等待）、出队到打分完成（计算）、打分完成到回填确认（回填）。三段各自记录 P50/P99，尖刺落在哪段就指向哪类机制。若尖刺集中在等待段且与队列深度正相关，是攒批策略问题；若集中在计算段且与序列长度相关，是桶划分或显存降批问题；若集中在回填段，是训练侧消费能力不足。代价上，三段打点增加日志量与时钟同步开销，但这是唯一能把“尾延迟”还原成可修机制的办法。具体例子：某轮迭代 P99 迭代时间突增，三段打点显示等待段平稳、计算段尖刺与某桶长序列同步出现，回溯到该桶未设 token 上限导致单批过大、触发降批重算——修桶上限后尖刺消失。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-43\">四十三 · 幂等与回滚：故障恢复的最小工程闭环</h3>\n<p>奖励服务重启或故障时，队列中在途样本面临丢失或重复打分。若回填缺少幂等键，训练侧会混入重复 reward 或缺失样本，前者让某条样本的优势被重复计入，后者让 batch 组成偏移。最小闭环是：每条样本在入队时分配全局唯一 id，回填时携带 id 与打分版本号；训练侧样本缓冲区按 id 去重写入，重复回填只保留首个有效结果，缺失样本在攒批超时后重新入队。</p>\n<p>回滚分两级。数值回滚：切回上一版量化配置与归约路径，锚定集重放验证通过后恢复回填。拓扑回滚：当扩容引发显存争抢或路由偏斜无法在线修复时，把奖励服务缩回故障前副本数与批策略，牺牲吞吐保稳定。回滚触发条件必须量化——$\\delta$ 的 P99 越界、队列深度方差越界、三段打点中任一段 P99 越界，任一满足即自动降级。代价是回滚期间打分吞吐下降、端到端迭代时间抬升，但避免了污染训练信号。具体例子：奖励服务滚动重启，未带幂等键的旧版回填导致同一批样本出现两条 reward，训练侧损失曲线出现单点跳变；引入 id 去重与版本号后，重启期间重复回填被静默丢弃，缺失样本在超时后重放，训练侧无感。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-44\">四十四 · 监控面板与容量判断：把失败模式映射成可观测指标</h3>\n<p>监控面板按失败模式组织，而非按资源组织。精度页放锚定集 $\\delta$ 分位点与 reward 分布漂移；显存页放桶级 token 峰值与降批次数；队列页放深度方差、批大小熵、两侧吞吐比；路由页放副本间桶分布与 P99 时延差；回填页放三段打点与幂等去重计数。每项指标绑定一个自动动作：越界即降批、切路由、冻结回填或缩容。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主指标</th><th>自动动作</th><th>代价</th></tr></thead><tbody><tr><td>精度漂移</td><td>锚定集 $\\delta$ P99</td><td>冻结回填、切数值配置</td><td>锚定集占用一个桶的 prefill 容量</td></tr><tr><td>OOM</td><td>桶级 token 峰值</td><td>按 token 预算拆批、降批</td><td>打分吞吐下降</td></tr><tr><td>批抖动</td><td>队列深度方差</td><td>调整攒批窗口、限流入队</td><td>重叠度下降，迭代时间向两者之和退化</td></tr><tr><td>路由不均</td><td>副本间 P99 时延差</td><td>长度感知路由重定向</td><td>回填时延增加一个网络往返</td></tr><tr><td>尾延迟尖刺</td><td>三段打点 P99</td><td>定位段后修桶上限或扩回填消费</td><td>日志与时钟同步开销</td></tr><tr><td>重复/丢失</td><td>幂等去重计数、缺失超时数</td><td>id 去重、超时重放</td><td>缓冲区额外索引内存</td></tr></tbody></table>\n<p>容量判断落在队列深度与弹性伸缩粒度的匹配上。扩容触发点若设得过晚，队列积压把 $T_{\\text{reward}}$ 推高到超过 $T_{\\text{rollout}}$，重叠收益归零；设得过早，副本频繁拉起又制造显存争抢。工程判断是：以队列深度方差与两侧吞吐比为双信号，方差上升且吞吐比持续偏离 1 时扩容，扩容粒度按桶容量而非按卡数，避免一次拉起过多副本冲击共享权重存储。规模上限由此确定——不是卡数上限，而是“队列深度 × 桶容量”与弹性伸缩响应时间的乘积上限；超过这个上限，分离式服务的异步重叠假设不再成立，应退回同步打分或缩小奖励模型规模。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-45\">四十五 · 当重叠失效：队列、幂等与显存的三类塌陷</h3>\n<p>这套分离式服务的收益完全建立在“重叠”二字上，而重叠最脆弱的地方不在奖励服务内部，而在两侧吞吐的匹配关系。设 rollout 侧产出速率为 $r_{\\text{out}}$（样本/秒），奖励服务按分桶攒批后的稳定处理速率为 $r_{\\text{rew}}$，则队列深度 $Q(t)$ 的漂移近似为 $\\dot Q = r_{\\text{out}} - r_{\\text{rew}}$。只要 $r_{\\text{out}} &gt; r_{\\text{rew}}$ 持续存在，队列无界增长，端到端时间就从 $\\max(T_{\\text{rollout}}, T_{\\text{reward}})$ 退化为 $T_{\\text{rollout}} + T_{\\text{reward}} + Q/r_{\\text{rew}}$——异步重叠在数学上已经失效，但监控面板上 rollout 引擎的采样吞吐仍然漂亮，这是最典型的“批抖动”误判：采样侧指标正常，训练迭代却在悄悄变慢。诊断口径必须是队列驻留时延的分位数而非均值，因为长序列样本在分桶队列尾部堆积时，均值被大量短样本稀释，尾延迟尖刺只体现在 p99 回填时延上。</p>\n<p>第二类塌陷是精度与幂等。奖励服务重启或队列消息重投时，若回填只带样本内容而不带唯一幂等键，训练侧样本缓冲区会混入重复 reward 或整条缺失，表现为 loss 曲线出现无法用学习率解释的阶跃，且这种污染不可逆——一旦策略更新消费了错误 reward，后续所有梯度都被带偏。工程上必须让幂等键在 rollout 侧生成时就绑定到样本 id，回填路径做去重表，且奖励服务的打分结果先落持久化再确认消费，宁可重复打分（代价是一次额外 prefill）也不能丢分。验证器场景更严苛：通过/不通过是二值信号，重复回填会直接改变正负样本比例。</p>\n<p>第三类是显存。奖励模型独立占一份权重，与策略模型、rollout 的 KV 池共享同一批卡时，弹性伸缩的触发点由队列深度决定，但扩容有分钟级滞后，缩容又过于激进就会在下一波长序列涌入时触发 OOM 或被迫降批——降批直接抬高 $T_{\\text{reward}}$，反过来加剧队列积压，形成正反馈。回滚策略应绑定在队列驻留时延而非单纯错误率上：当 p99 回填时延越过阈值，先把奖励服务切回与 rollout 同卡混部的保守配置（牺牲 prefill 效率换确定性），再排查分桶策略是否被超长序列击穿。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>吞吐失配</td><td>队列驻留 p99 单调上升</td><td>迭代时间退化为两者之和</td><td>按队列深度扩容或限流 rollout</td></tr><tr><td>重复/丢失打分</td><td>样本 id 去重表命中率异常</td><td>梯度污染，不可逆</td><td>幂等键+先落盘后确认</td></tr><tr><td>显存争抢</td><td>降批事件与 OOM 计数</td><td>奖励吞吐下降，正反馈积压</td><td>回滚至混部保守配置</td></tr></tbody></table>\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-46\">四十六 · 同族算法的选择维度：先问\"瓶颈在哪一侧\"</h3>\n<p>奖励模型分离式服务不是孤立选项，它和分页 KV 批量 Rollout、分块预填背驮解码、预填解码分离 Rollout、KV 中心分离式池化、特征级投机采样 Rollout、批不变 Rollout 采样、异步 Rollout 流水线、在线 Rollout 剪枝、异构 Agent 协同 Rollout、Rollout 前缀 KV 共享、分块预填搭载解码这些条目处在同一个 RL 后训练推理栈里。选型的第一个问题不是\"哪个更快\"，而是\"当前迭代时间里，rollout 生成与奖励打分谁占大头，以及两者是否共享同一批 GPU 资源\"。若 $T_{\\text{rollout}} \\gg T_{\\text{reward}}$，奖励打分即使串行执行也只占迭代时间的零头，分离式服务的收益被淹没在生成侧，此时应优先考虑分页 KV 批量 Rollout 或前缀 KV 共享来压生成时间；反之若奖励模型是长序列验证器、打分 prefill 极重，$T_{\\text{reward}}$ 接近甚至超过 $T_{\\text{rollout}}$，分离式服务把两者从\"和\"变成\"最大值\"的价值才成立。这条判据直接对应公式 $T_{\\text{iter}} \\approx \\max(T_{\\text{rollout}}, T_{\\text{reward}}) + T_{\\text{train}}$：只有当被 max 的两项量级可比时，重叠才有意义。</p>\n<p>第二个维度是资源耦合度。奖励模型与策略模型同卡部署时争抢的是同一份显存与 SM，而奖励输入是完整长序列、prefill 重，batch 组成与 decode 主导的 rollout 完全不同，混部会把两侧都拖到低效工作点。分离式服务用独立 KV 池、共享权重存储的方式切断这种耦合，代价是多占一份权重显存。因此在小模型集群上，分离式的显存代价可能超过它节省的时间——这是与 KV 中心分离式池化最本质的分野：后者把 KV 集中池化以提升复用，前者把计算角色拆开以消除干扰，两者的资源账本方向相反。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-47\">四十七 · 决策表：五类相邻算法的适用条件对照</h3>\n<p>下表把同族条目按\"解决的主要矛盾\"与\"触发条件\"对齐，便于在给定集群形态与负载配方时快速排除不适用项。表中不重复各条目自身的机制细节，只保留选型判据。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>算法条目</th><th>主要矛盾</th><th>适用触发条件</th><th>不适用/让位条件</th></tr>\n</thead>\n<tbody>\n<tr><td>奖励模型分离式服务</td><td>打分 prefill 与 rollout decode 争抢同卡资源、batch 形态冲突</td><td>$T_{\\text{reward}}$ 与 $T_{\\text{rollout}}$ 量级可比；奖励输入为长完整序列；集群可容纳独立权重副本</td><td>奖励极轻（短序列、小模型）；显存紧张到无法多放一份权重</td></tr>\n<tr><td>异步 Rollout 流水线</td><td>生成与训练串行导致 GPU 空转</td><td>训练侧更新与生成侧可解耦；样本新鲜度容忍度高</td><td>需要严格 on-policy 同步；奖励打分本身是瓶颈（此时应叠加分离式服务）</td></tr>\n<tr><td>预填解码分离 Rollout</td><td>prefill 与 decode 在同一引擎内互相干扰</td><td>策略模型自身 prefill 占比高、序列长</td><td>瓶颈在奖励侧而非策略侧；短序列 decode 主导</td></tr>\n<tr><td>KV 中心分离式池化</td><td>KV 显存碎片化、跨请求复用率低</td><td>多轮/共享前缀场景，KV 复用收益显著</td><td>奖励打分是一次性完整序列、无跨样本 KV 复用价值</td></tr>\n<tr><td>分块预填搭载解码 / 背驮解码</td><td>单引擎内 prefill 空窗期浪费算力</td><td>prefill 与 decode 可在同卡交错调度</td><td>奖励与策略已物理分离，无需引擎内交错</td></tr>\n</tbody>\n</table>\n<p>读表的方式是自上而下排除：先看奖励侧是否构成瓶颈，若不是，分离式服务直接出局，转向生成侧优化条目；若是，再看集群是否有显存余量容纳独立权重，若没有，则退化为同卡混部加异步流水线，接受 $T_{\\text{iter}}$ 退化为两者之和的代价。表中\"异步 Rollout 流水线\"与\"奖励模型分离式服务\"是互补而非互斥：前者解决生成与训练的时序重叠，后者解决生成与打分的资源隔离，二者叠加才构成完整的\"生成—打分—训练\"三段流水。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-48\">四十八 · 吞吐匹配的定量判据：队列深度与两侧速率</h3>\n<p>选型不能只靠定性，需要把两侧吞吐折算到同一时间尺度。奖励服务的吞吐由分桶攒批后的 prefill 能力决定，其表达式为 $\\text{throughput}_{\\text{reward}} = N_{\\text{samples}} / \\sum L_{\\text{sample}} / \\text{thr}_{\\text{reward\\_prefill}}$，即单位时间内能打分的样本数受限于总 token 量与奖励 prefill 速率之比。rollout 侧的产出速率则是每迭代生成的样本数除以 $T_{\\text{rollout}}$。设队列深度为 $Q$，稳态下队列不无限增长的条件是产出速率不超过打分速率；一旦打分速率低于产出速率，队列深度单调上升，回填时延拉长，训练侧等待 reward 的时间从\"被 max 掩盖\"变为\"显式暴露\"，端到端时间退化为 $T_{\\text{rollout}} + T_{\\text{reward}}$，异步重叠失效——这正是失败模式中\"队列深度与两侧吞吐不匹配\"的定量根源。</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{reward}} = \\frac{N_{\\text{samples}}}{\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}} \\;\\ge\\; \\frac{N_{\\text{samples}}}{T_{\\text{rollout}}}$$</div>\n<p>该不等式给出弹性扩缩容的触发点：当实测队列深度持续超过设计水位（例如连续若干个调度周期只增不减），说明右侧产出速率已压过左侧打分速率，需按队列深度扩容奖励服务副本或提高其并行度。反过来，若队列长期为空，说明奖励服务过度配置，应缩容以释放显存给 rollout 的 KV 池。举例：一个以长文档验证器为奖励的 RLVR 配方，单样本长度分布在数千 token 量级，奖励 prefill 是纯计算密集的长序列打分，此时 $\\sum L_{\\text{sample}}$ 很大、打分速率成为硬约束，分离式服务必须配合长度分桶攒批才能把 padding 浪费压下去；而若奖励是短序列分类头，$\\sum L_{\\text{sample}}$ 小，打分速率远高于产出，分离式服务的独立权重显存就变成纯开销，应让位给同卡混部。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-49\">四十九 · 与\"预填解码分离\"和\"KV 池化\"的边界划分</h3>\n<p>工程上最容易混淆的是三者都叫\"分离\"，但分离的对象不同。预填解码分离 Rollout 分离的是同一模型内部的两种计算阶段，目的是让 prefill 与 decode 各自跑在最优并行拓扑上，KV 仍在策略模型侧；KV 中心分离式池化分离的是存储与计算，把 KV 从各引擎私有显存搬到共享池以提升跨请求复用；奖励模型分离式服务分离的是模型角色，奖励模型拥有自己的权重、自己的 KV 池、自己的批调度器，与策略引擎只通过样本队列与结果回填通信。判断依据很直接：若被分离的两侧共享同一份模型权重，属于前两者；若两侧权重不同、输入分布不同、最优 batch 形态不同，才属于角色分离。</p>\n<p>这条边界决定了能否复用基础设施。奖励服务可以与 rollout 引擎共享权重存储（同一套权重加载路径、同一份量化格式），但必须使用独立 KV 池，因为奖励打分的 KV 生命周期是\"单样本一次性\"，与 rollout 的多轮增量 decode 完全不同，混用池会引入无谓的碎片与换入换出。系统代价上，独立 KV 池意味着显存账本上多一笔固定开销，其规模按奖励模型的最大批与最大序列长度配置；这笔开销换来的收益是打分侧不再被 rollout 的 KV 增长挤压，避免因 rollout 突发长序列而触发奖励服务的降批或 OOM。与分块预填搭载解码相比，后者在单引擎内利用 prefill 空窗搭载 decode，本质是时间维度的填缝；奖励分离式服务则是空间维度的隔离，两者可以并存：策略引擎内部用搭载解码提利用率，引擎外部用独立奖励服务消除跨模型干扰。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-50\">五十 · 组合选型的工程判断：按集群规模分档</h3>\n<p>把上述判据落到集群规模上，可得到三档组合建议。小规模集群（少量节点、显存紧张）：奖励模型与策略模型同卡混部，叠加异步 Rollout 流水线与批不变采样，接受 $T_{\\text{iter}}$ 退化为两者之和的风险，用队列深度监控提前预警；此时不应引入独立奖励服务，因为多一份权重显存会直接压缩 rollout 的 KV 空间，弹性伸缩粒度也不足以覆盖抖动。中等规模（多节点、显存有余量）：奖励服务独立部署但与其共享权重存储，按长度分桶攒批，配合预填解码分离 Rollout 优化策略侧 prefill；这是分离式服务收益最明显的区间，因为两侧吞吐量级可比且资源不再互斥。大规模 NVL72 级集群：奖励服务按队列深度独立扩缩容，与 KV 中心分离式池化、前缀 KV 共享、特征级投机采样等条目组合，形成\"生成侧多路优化 + 打分侧独立扩容\"的完整流水，此时选型的关键不再是\"要不要分离\"，而是\"分离后各侧的并行拓扑与硬件档位如何按自身最优 prefill 配置对齐\"。</p>\n<p>最后一条工程判断落在幂等与故障域上：无论选哪一档，只要引入样本队列与异步回填，就必须在回填路径上带样本 id 作为幂等键，使奖励服务重启后的重复打分不会污染训练侧缓冲区。这是分离式服务区别于其他条目的独有代价——其他条目优化的是算力与带宽，它额外引入了一个跨服务的状态一致性问题；选型时若团队没有队列与回填的运维能力，宁可退回到同卡混部加异步流水线，也不要在没有幂等保障的情况下贸然拆分。</p>\n\n<h3 id=\"alg-rm-verifier-disagg-serving-sec-51\">五十一 · 同族对照：何时拆、何时合、何时换验证器</h3>\n<p>把奖励服务拆出去并非普适解，它的收益边界由重叠率决定。设两侧吞吐匹配度为 $\\rho=\\min(T_{\\text{rollout}},T_{\\text{reward}})/\\max(T_{\\text{rollout}},T_{\\text{reward}})$，则实际迭代时间 $T_{\\text{iter}}\\approx\\max(T_{\\text{rollout}},T_{\\text{reward}})+T_{\\text{train}}$ 只在队列深度足以吸收抖动、且 $\\rho$ 接近 1 时成立；一旦奖励侧 prefill 吞吐长期低于 rollout 产出速率，队列单调增长，端到端时间退化为两者之和，异步重叠归零。此时正确动作不是加深队列，而是按 $\\text{throughput}_{\\text{reward}}=N_{\\text{samples}}/\\sum L_{\\text{sample}}/\\text{thr}_{\\text{reward\\_prefill}}$ 反推所需副本数，或改用更轻的验证器（规则校验、短上下文判别头）替代全序列奖励模型打分。</p>\n<p>同族方案可归为三类：同卡混部、独立服务、以及把打分折叠进 rollout 引擎的尾部。混部在奖励模型极小、序列短、集群只有单机时总显存最省，代价是 decode 与 prefill 互相打断、batch 组成冲突；独立服务在长序列、大奖励模型、多机场景下吞吐最优，代价是多一份权重显存与队列幂等逻辑；折叠式适合验证器极轻、结果可即时判定的 RLVR 场景，省掉跨服务回填但失去独立扩缩容。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选型</th><th>主要代价</th></tr></thead><tbody><tr><td>奖励模型权重远小于策略模型、单机可容纳</td><td>同卡混部</td><td>prefill 与 decode 争抢，打分吞吐下降</td></tr><tr><td>输入为变长完整长序列、需按长度分桶攒批</td><td>独立奖励服务</td><td>独立权重显存、队列与幂等回填</td></tr><tr><td>验证器为规则或轻量判别、判定即时</td><td>折叠进 rollout 尾部</td><td>无独立弹性，抖动传导至采样</td></tr><tr><td>队列深度长期上涨、$\\rho$ 持续偏低</td><td>扩副本或换轻验证器</td><td>扩缩容粒度受显存与拓扑约束</td></tr></tbody></table>\n<p>失效条件集中在三处：奖励服务重启时队列内样本丢失或重复打分，回填缺少幂等键会让训练侧混入重复 reward 或缺失样本，必须用样本 id 做幂等写入；小规模集群上独立权重与策略模型、KV 池争抢显存，弹性伸缩不及时直接触发 OOM 或降批，此时应退回混部并接受吞吐损失；队列深度与两侧吞吐不匹配时，异步结构反而放大尾延迟。工程判断是：先测 $\\rho$ 与队列稳态深度，再决定拆合，而不是默认拆分。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 离策略程度与陈旧度控制</td></tr><tr><td>解决什么</td><td>RLHF/RLVR的rollout后需要对每条样本跑奖励模型或验证器推理，奖励模型与策略模型若同卡部署会互相抢占显存与…</td></tr><tr><td>一句话机制</td><td>把奖励模型/验证器拆为独立推理服务，rollout引擎生成完样本后把token序列经队列送入奖励服务，奖励服务按自身最…</td></tr><tr><td>代价与失效</td><td>奖励服务与rollout引擎间需维护样本队列与结果回填，故障时样本丢失或重复打分需幂等处理；奖励模型显存独立占用一份权重，小模型集群上总显…</td></tr><tr><td>后继</td><td>NVFP4量化Rollout稳定化</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-rm-verifier-disagg-serving · 共 8 个片段</p>\n";break;}}})();
